function prepareSourceHttpRequest(raw) {
  if (!raw || typeof raw !== "object") return null;
  const allowedKeys = new Set([
    "url",
    "method",
    "multiValueQueryString",
    "headers",
    "body",
    "json",
  ]);
  const prepared = {};
  for (const key of allowedKeys) {
    if (!Object.prototype.hasOwnProperty.call(raw, key)) continue;
    const value = raw[key];
    if (value === undefined) continue;
    prepared[key] = value;
  }
  if (!prepared.url || !prepared.method) {
    return null;
  }
  return prepared;
}

function resolveSourceHttpRequest(...candidates) {
  for (const candidate of candidates) {
    const prepared = prepareSourceHttpRequest(candidate);
    if (prepared) {
      return prepared;
    }
  }
  return null;
}

function extractCoordinatesFromHTML(html) {
  const fallback = { latitude: null, longitude: null };
  if (typeof html !== "string" || !html.length) {
    return fallback;
  }

  const candidatePatterns = [
    /"latitude"\s*:\s*(-?\d+\.\d+)[^}]{0,200}"longitude"\s*:\s*(-?\d+\.\d+)/i,
    /"lat"\s*[:=]\s*(-?\d+\.\d+)[^}]{0,200}"(?:lng|lon|longitude)"\s*[:=]\s*(-?\d+\.\d+)/i,
    /lat\s*=\s*(-?\d+\.\d+)[^,\n]{0,120},\s*(?:lng|lon|long)\s*=\s*(-?\d+\.\d+)/i,
    /data-latitude\s*=\s*"(-?\d+\.\d+)"[^>]{0,200}data-longitude\s*=\s*"(-?\d+\.\d+)"/i,
  ];

  for (const pattern of candidatePatterns) {
    const match = html.match(pattern);
    if (match) {
      const [, lat, lon] = match;
      return { latitude: lat, longitude: lon };
    }
  }

  const latitudeMatch =
    html.match(/"latitude"\s*:\s*(-?\d+\.\d+)/i) ||
    html.match(/\blat(?:itude)?\b["'\s:=]+(-?\d+\.\d+)/i);
  const longitudeMatch =
    html.match(/"longitude"\s*:\s*(-?\d+\.\d+)/i) ||
    html.match(/\b(?:lng|lon|longitude)\b["'\s:=]+(-?\d+\.\d+)/i);

  if (latitudeMatch && longitudeMatch) {
    return { latitude: latitudeMatch[1], longitude: longitudeMatch[1] };
  }

  return fallback;
}

function writeRelationshipFile(filePath, fromValue, toValue) {
  const baseName = path.basename(filePath, ".json");
  const normalizedBaseName = baseName.replace(/_\d+$/, "");
  if (
    RELATIONSHIP_AUTOGENERATED_BASENAMES.has(baseName) ||
    RELATIONSHIP_AUTOGENERATED_BASENAMES.has(normalizedBaseName)
  ) {
    removeFileIfExists(filePath);
    return;
  }

  try {
    fs.writeFileSync(filePath, "null\n");
  } catch {
    removeFileIfExists(filePath);
  }
}

function removeFileIfExists(filePath) {
  if (fs.existsSync(filePath)) {
    fs.unlinkSync(filePath);
  }
}

function extractBetween(html, regex, idx = 1) {
  const m = html.match(regex);
  return m ? (m[idx] || "").trim() : null;
}

function finalizeCountyAddressNormalization(addressFilePath, options = {}) {
  if (!addressFilePath || !fs.existsSync(addressFilePath)) {
    return;
  }

  let payload;
  try {
    payload = readJSON(addressFilePath);
  } catch {
    return;
  }

  if (!payload || typeof payload !== "object" || Array.isArray(payload)) {
    return;
  }

  const trimmedRaw =
    typeof payload.unnormalized_address === "string"
      ? payload.unnormalized_address.trim()
      : "";

  const rawCandidates = [];
  if (trimmedRaw.length) rawCandidates.push(trimmedRaw);
  if (Array.isArray(options.rawCandidates)) {
    for (const candidate of options.rawCandidates) {
      if (typeof candidate !== "string") continue;
      const trimmed = candidate.trim();
      if (!trimmed.length) continue;
      if (!rawCandidates.includes(trimmed)) {
        rawCandidates.push(trimmed);
      }
    }
  }

  if (rawCandidates.length) {
    strengthenAddressFromRawCandidates(payload, rawCandidates);
  }

  const resolveCandidate = (candidates) =>
    resolveFirstNonEmptyString(
      Array.isArray(candidates) ? candidates : [],
    );

  const ensureField = (field, candidates) => {
    if (hasMeaningfulAddressValue(payload[field])) return;
    const resolved = resolveCandidate(candidates);
    if (hasMeaningfulAddressValue(resolved)) {
      payload[field] = resolved;
    }
  };

  ensureField("city_name", options.cityCandidates);
  ensureField("municipality_name", options.municipalityCandidates);
  ensureField("postal_code", options.postalCandidates);
  ensureField("plus_four_postal_code", options.plus4Candidates);
  ensureField("county_name", options.countyCandidates);
  ensureField("state_code", options.stateCandidates);

  if (!hasMeaningfulAddressValue(payload.country_code)) {
    const resolvedCountry =
      resolveCandidate(options.countryCandidates) ||
      (hasMeaningfulAddressValue(payload.state_code)
        ? options.defaultCountryCode || "US"
        : null);
    if (hasMeaningfulAddressValue(resolvedCountry)) {
      payload.country_code = resolvedCountry;
    }
  }

  if (
    !hasMeaningfulAddressValue(payload.county_name) &&
    hasMeaningfulAddressValue(options.defaultCountyName)
  ) {
    payload.county_name = options.defaultCountyName;
  }
  if (
    !hasMeaningfulAddressValue(payload.state_code) &&
    hasMeaningfulAddressValue(options.defaultStateCode)
  ) {
    payload.state_code = options.defaultStateCode;
  }
  if (
    !hasMeaningfulAddressValue(payload.country_code) &&
    hasMeaningfulAddressValue(options.defaultCountryCode)
  ) {
    payload.country_code = options.defaultCountryCode;
  }

  const normalizedSurface = { ...NORMALIZED_ADDRESS_SCHEMA_TEMPLATE };
  for (const field of NORMALIZED_ADDRESS_FIELDS) {
    normalizedSurface[field] = sanitizeAddressFieldValue(
      field,
      payload[field],
    );
  }

  if (!normalizedSurface.postal_code) {
    normalizedSurface.plus_four_postal_code = null;
  }
  if (normalizedSurface.state_code && !normalizedSurface.country_code) {
    normalizedSurface.country_code = options.defaultCountryCode || "US";
  }
  if (
    (normalizedSurface.latitude == null) !==
    (normalizedSurface.longitude == null)
  ) {
    normalizedSurface.latitude = null;
    normalizedSurface.longitude = null;
  }
  if (
    !hasMeaningfulAddressValue(normalizedSurface.county_name) &&
    hasMeaningfulAddressValue(options.defaultCountyName)
  ) {
    normalizedSurface.county_name = options.defaultCountyName;
  }

  const normalizedProbe = { ...normalizedSurface };
  const normalizedCoverage =
    typeof hasRobustNormalizedAddress === "function"
      ? hasRobustNormalizedAddress({ ...normalizedProbe })
      : hasNormalizedCountyCoverage(normalizedProbe);

  if (normalizedCoverage) {
    const normalizedRequestIdentifier = resolveRequestIdentifierCandidate(
      normalizedProbe.request_identifier,
      payload.request_identifier,
      ...(Array.isArray(options.requestIdentifierCandidates)
        ? options.requestIdentifierCandidates
        : []),
    );
    const normalizedSourceHttpRequest = resolveSourceHttpRequestCandidate(
      normalizedProbe.source_http_request,
      payload.source_http_request,
      ...(Array.isArray(options.sourceHttpRequestCandidates)
        ? options.sourceHttpRequestCandidates
        : []),
    );
    if (!normalizedSourceHttpRequest) {
      removeFileIfExists(addressFilePath);
      return;
    }

    const normalizedOutput = { ...NORMALIZED_ADDRESS_SCHEMA_TEMPLATE };
    for (const field of NORMALIZED_ADDRESS_FIELDS) {
      normalizedOutput[field] =
        normalizedProbe[field] === undefined ||
        normalizedProbe[field] === null
          ? null
          : normalizedProbe[field];
    }
    normalizedOutput.request_identifier =
      normalizedRequestIdentifier !== undefined &&
      normalizedRequestIdentifier !== null
        ? normalizedRequestIdentifier
        : null;
    normalizedOutput.source_http_request = normalizedSourceHttpRequest;

    fs.writeFileSync(
      addressFilePath,
      JSON.stringify(normalizedOutput, null, 2),
    );
    return;
  }

  const finalRawCandidates = [...rawCandidates];
  if (!finalRawCandidates.length) {
    const composed = composeUnnormalizedAddress(normalizedSurface);
    if (hasMeaningfulAddressValue(composed)) {
      finalRawCandidates.push(composed);
    }
  }

  const resolvedRaw = resolveFirstNonEmptyString(finalRawCandidates);
  const trimmedResolved =
    typeof resolvedRaw === "string" ? resolvedRaw.trim() : "";
  if (!trimmedResolved.length && !trimmedRaw.length) {
    removeFileIfExists(addressFilePath);
    return;
  }
  const rawString = trimmedResolved || trimmedRaw;

  const rawRequestIdentifier = resolveRequestIdentifierCandidate(
    payload.request_identifier,
    normalizedSurface.request_identifier,
    ...(Array.isArray(options.requestIdentifierCandidates)
      ? options.requestIdentifierCandidates
      : []),
  );
  const rawSourceHttpRequest = resolveSourceHttpRequestCandidate(
    payload.source_http_request,
    normalizedSurface.source_http_request,
    ...(Array.isArray(options.sourceHttpRequestCandidates)
      ? options.sourceHttpRequestCandidates
      : []),
  );
  if (!rawSourceHttpRequest) {
    removeFileIfExists(addressFilePath);
    return;
  }

  const rawPayload = buildRawAddressOneOfPayload(
    rawString,
    rawRequestIdentifier ?? null,
    rawSourceHttpRequest,
    payload,
  );
  if (!rawPayload) {
    removeFileIfExists(addressFilePath);
    return;
  }

  fs.writeFileSync(addressFilePath, JSON.stringify(rawPayload, null, 2));
}

function emitSchemaCompliantCountyAddress(addressPath, options = {}) {
  if (!addressPath || !fs.existsSync(addressPath)) {
    return;
  }

  const payload = readJSONIfExists(addressPath);
  if (!payload || typeof payload !== "object" || Array.isArray(payload)) {
    return;
  }

  const {
    unnormalizedPath = null,
    seedPath = null,
    defaultCountryCode = "US",
    extraRawCandidates = [],
    preferNormalized: preferNormalizedOption,
    coordinateCandidates = [],
  } = options || {};

  const normalizedSurface = { ...NORMALIZED_ADDRESS_SCHEMA_TEMPLATE };
  for (const field of NORMALIZED_ADDRESS_FIELDS) {
    const sanitized = sanitizeAddressFieldValue(field, payload[field]);
    normalizedSurface[field] =
      sanitized === undefined || sanitized === null ? null : sanitized;
  }

  const normalizeCoordinate = (value) => {
    const numeric = parseCoordinate(value);
    return Number.isFinite(numeric) ? numeric : null;
  };
  normalizedSurface.latitude = normalizeCoordinate(normalizedSurface.latitude);
  normalizedSurface.longitude = normalizeCoordinate(
    normalizedSurface.longitude,
  );
  if (
    (normalizedSurface.latitude == null) !==
    (normalizedSurface.longitude == null)
  ) {
    normalizedSurface.latitude = null;
    normalizedSurface.longitude = null;
  }

  if (!normalizedSurface.postal_code) {
    normalizedSurface.plus_four_postal_code = null;
  }
  if (normalizedSurface.state_code && !normalizedSurface.country_code) {
    normalizedSurface.country_code = (defaultCountryCode || "US").toUpperCase();
  }

  const candidateSources = [payload];
  const unnormalizedSource = readJSONIfExists(unnormalizedPath);
  if (unnormalizedSource && typeof unnormalizedSource === "object") {
    candidateSources.push(unnormalizedSource);
  }
  const seedSource = readJSONIfExists(seedPath);
  if (seedSource && typeof seedSource === "object") {
    candidateSources.push(seedSource);
  }
  if (
    ADDRESS_FALLBACK_CONTEXT &&
    Array.isArray(ADDRESS_FALLBACK_CONTEXT.fieldSources)
  ) {
    for (const source of ADDRESS_FALLBACK_CONTEXT.fieldSources) {
      if (source && typeof source === "object") {
        candidateSources.push(source);
      }
    }
  }

  const collectFieldCandidates = (field) =>
    candidateSources
      .map((source) => {
        if (!source || typeof source !== "object") return null;
        return source[field];
      })
      .filter((value) => value !== undefined && value !== null);

  const requestIdentifierQueue = [
    payload.request_identifier,
    ...collectFieldCandidates("request_identifier"),
  ];
  if (
    ADDRESS_FALLBACK_CONTEXT &&
    Array.isArray(ADDRESS_FALLBACK_CONTEXT.requestIdentifierCandidates)
  ) {
    requestIdentifierQueue.push(
      ...ADDRESS_FALLBACK_CONTEXT.requestIdentifierCandidates,
    );
  }
  const resolvedRequestIdentifier = safeNullIfEmpty(
    resolveFirstNonEmptyString(requestIdentifierQueue),
  );

  const sourceHttpCandidates = [
    payload.source_http_request,
    ...collectFieldCandidates("source_http_request"),
  ].filter((candidate) => candidate && typeof candidate === "object");

  if (
    ADDRESS_FALLBACK_CONTEXT &&
    Array.isArray(ADDRESS_FALLBACK_CONTEXT.sourceHttpRequestCandidates)
  ) {
    sourceHttpCandidates.push(
      ...ADDRESS_FALLBACK_CONTEXT.sourceHttpRequestCandidates.filter(
        (candidate) => candidate && typeof candidate === "object",
      ),
    );
  }

  const resolvedSourceHttpRequest = resolveSourceHttpRequestCandidate(
    ...sourceHttpCandidates,
  );

  const coordinateQueue = [];
  const enqueueCoordinateCandidate = (candidate) => {
    if (!candidate || typeof candidate !== "object") return;
    const hasLatitude = Object.prototype.hasOwnProperty.call(
      candidate,
      "latitude",
    );
    const hasLongitude = Object.prototype.hasOwnProperty.call(
      candidate,
      "longitude",
    );
    if (!hasLatitude && !hasLongitude) return;
    coordinateQueue.push({
      latitude: candidate.latitude,
      longitude: candidate.longitude,
    });
  };

  enqueueCoordinateCandidate(normalizedSurface);
  candidateSources.forEach(enqueueCoordinateCandidate);
  if (Array.isArray(coordinateCandidates)) {
    coordinateCandidates.forEach(enqueueCoordinateCandidate);
  }
  if (
    ADDRESS_FALLBACK_CONTEXT &&
    Array.isArray(ADDRESS_FALLBACK_CONTEXT.coordinateCandidates)
  ) {
    ADDRESS_FALLBACK_CONTEXT.coordinateCandidates.forEach(
      enqueueCoordinateCandidate,
    );
  }

  const resolvedCoordinate = resolveCoordinateFromCandidates(coordinateQueue);
  if (resolvedCoordinate) {
    normalizedSurface.latitude = resolvedCoordinate.latitude;
    normalizedSurface.longitude = resolvedCoordinate.longitude;
  }

  const rawCandidates = [];
  const pushRawCandidate = (value) => {
    if (typeof value !== "string") return;
    const trimmed = value.trim();
    if (trimmed.length) {
      rawCandidates.push(trimmed);
    }
  };

  const harvestRawStrings = (source) => {
    if (!source || typeof source !== "object") return;
    pushRawCandidate(source.unnormalized_address);
    pushRawCandidate(source.full_address);
    pushRawCandidate(source.site_address);
    pushRawCandidate(source.address);
    pushRawCandidate(source.raw_address);
    pushRawCandidate(source.location_address);
    pushRawCandidate(source.mail_address);
    if (Array.isArray(source.lines)) {
      for (const line of source.lines) {
        pushRawCandidate(line);
      }
      pushRawCandidate(source.lines.join(", "));
    }
  };

  candidateSources.forEach(harvestRawStrings);

  if (Array.isArray(extraRawCandidates)) {
    extraRawCandidates.forEach(pushRawCandidate);
  }

  if (
    ADDRESS_FALLBACK_CONTEXT &&
    Array.isArray(ADDRESS_FALLBACK_CONTEXT.unnormalizedCandidates)
  ) {
    ADDRESS_FALLBACK_CONTEXT.unnormalizedCandidates.forEach(
      pushRawCandidate,
    );
  }

  if (
    typeof composeFallbackUnnormalizedAddressFromFields === "function"
  ) {
    pushRawCandidate(
      composeFallbackUnnormalizedAddressFromFields({ ...normalizedSurface }),
    );
  }

  const resolvedRaw = resolveFirstNonEmptyString(rawCandidates);
  const trimmedRaw =
    typeof resolvedRaw === "string" ? resolvedRaw.trim() : "";

  const basePayload = { ...NORMALIZED_ADDRESS_SCHEMA_TEMPLATE };
  for (const field of NORMALIZED_ADDRESS_FIELDS) {
    basePayload[field] =
      normalizedSurface[field] === undefined ||
      normalizedSurface[field] === null
        ? null
        : normalizedSurface[field];
  }
  basePayload.request_identifier =
    resolvedRequestIdentifier === undefined
      ? null
      : resolvedRequestIdentifier;
  basePayload.source_http_request = resolvedSourceHttpRequest
    ? deepClone(resolvedSourceHttpRequest)
    : null;

  const normalizedCandidate =
    buildNormalizedAddressOutputForSchema({
      ...normalizedSurface,
      unnormalized_address: undefined,
    }) || null;
  const normalizedReady =
    normalizedCandidate &&
    hasRobustNormalizedAddress({ ...normalizedCandidate });

  const preferNormalized =
    preferNormalizedOption !== undefined
      ? Boolean(preferNormalizedOption)
      : trimmedRaw.length === 0;
  const shouldEmitNormalized = normalizedReady && preferNormalized;

  if (shouldEmitNormalized) {
    const normalizedOutput = { ...NORMALIZED_ADDRESS_SCHEMA_TEMPLATE };
    for (const field of NORMALIZED_ADDRESS_FIELDS) {
      normalizedOutput[field] =
        normalizedCandidate[field] === undefined ||
        normalizedCandidate[field] === null
          ? null
          : normalizedCandidate[field];
    }
    if (
      Object.prototype.hasOwnProperty.call(
        normalizedOutput,
        "unnormalized_address",
      )
    ) {
      delete normalizedOutput.unnormalized_address;
    }
    normalizedOutput.request_identifier =
      resolvedRequestIdentifier === undefined
        ? null
        : resolvedRequestIdentifier;
    normalizedOutput.source_http_request = resolvedSourceHttpRequest
      ? deepClone(resolvedSourceHttpRequest)
      : null;
    writeJSON(addressPath, normalizedOutput);
    return;
  }

  if (!trimmedRaw.length) {
    removeFileIfExists(addressPath);
    return;
  }

  const rawPayload =
    buildRawAddressOneOfPayload(
      trimmedRaw,
      resolvedRequestIdentifier,
      resolvedSourceHttpRequest,
      basePayload,
    ) || null;
  if (!rawPayload) {
    removeFileIfExists(addressPath);
    return;
  }

  writeJSON(addressPath, rawPayload);
}

function toISODate(mdy) {
  if (!mdy) return null;
  const m = String(mdy).trim();
  const parts = m.split("/");
  if (parts.length !== 3) return null;
  const [mm, dd, yyyy] = parts.map((x) => x.trim());
  if (!yyyy || !mm || !dd) return null;
  const MM = mm.padStart(2, "0");
  const DD = dd.padStart(2, "0");
  return `${yyyy}-${MM}-${DD}`;
}

function safeNullIfEmpty(s) {
  if (s == null) return null;
  const t = String(s).trim();
  return t === "" ? null : t;
}

function normalizeWhitespace(value) {
  if (!value) return "";
  return String(value).replace(/\s+/g, " ").trim();
}

function pickFirstMeaningfulString(candidates = []) {
  if (!Array.isArray(candidates)) {
    return null;
  }
  for (const candidate of candidates) {
    if (typeof candidate !== "string") continue;
    const trimmed = candidate.trim();
    if (trimmed.length) {
      return trimmed;
    }
  }
  return null;
}

function pickPreferredSourceHttpRequest(candidates = [], fallback = null) {
  const queue = Array.isArray(candidates) ? [...candidates] : [];
  if (fallback) {
    queue.push(fallback);
  }
  for (const candidate of queue) {
    const prepared = prepareSourceHttpRequest(candidate);
    if (prepared) {
      return prepared;
    }
  }
  return null;
}

function collectRawAddressCandidatesFromSource(target, source) {
  if (!Array.isArray(target) || !source || typeof source !== "object") {
    return;
  }
  const candidateFields = [
    "unnormalized_address",
    "full_address",
    "site_address",
    "address",
    "raw_address",
    "location_address",
    "mail_address",
  ];
  for (const field of candidateFields) {
    const normalized = safeNullIfEmpty(source[field]);
    if (normalized) {
      target.push(normalized);
    }
  }
  if (Array.isArray(source.lines)) {
    const joined = source.lines
      .map((line) => (typeof line === "string" ? line.trim() : ""))
      .filter((line) => line.length)
      .join(", ");
    if (joined.length) {
      target.push(joined);
    }
  }
}

function enforceRestrictedRelationshipNullOutputs(targetDirs = []) {
  if (!Array.isArray(targetDirs) || !targetDirs.length) {
    return;
  }
  const restrictedNames = Array.from(RELATIONSHIP_AUTOGENERATED_BASENAMES);
  for (const dirPath of targetDirs) {
    if (!dirPath || !fs.existsSync(dirPath)) continue;
    let entries = [];
    try {
      entries = fs.readdirSync(dirPath);
    } catch {
      continue;
    }
    for (const entry of entries) {
      if (!entry.endsWith(".json")) continue;
      const baseName = entry.replace(/\.json$/, "");
      const normalizedBase = baseName.replace(/_\d+$/, "");
      if (
        RELATIONSHIP_AUTOGENERATED_BASENAMES.has(baseName) ||
        RELATIONSHIP_AUTOGENERATED_BASENAMES.has(normalizedBase)
      ) {
        const filePath = path.join(dirPath, entry);
        try {
          fs.writeFileSync(filePath, "null\n");
        } catch {
          removeFileIfExists(filePath);
        }
      }
    }
    ensureNullRelationshipPlaceholders(dirPath, restrictedNames);
  }
}

function enforceRawOnlyAddressOutput(addressPath, options = {}) {
  if (!addressPath) return;

  const fallbackSources = [];
  const appendSource = (source) => {
    if (source && typeof source === "object") {
      fallbackSources.push(source);
    }
  };

  appendSource(readJSONIfExists(addressPath));

  const fallbackPaths = Array.isArray(options.fallbackPaths)
    ? options.fallbackPaths
    : [];
  for (const fallbackPath of fallbackPaths) {
    appendSource(readJSONIfExists(fallbackPath));
  }

  if (Array.isArray(options.extraSources)) {
    for (const source of options.extraSources) {
      appendSource(source);
    }
  }

  if (
    ADDRESS_FALLBACK_CONTEXT &&
    Array.isArray(ADDRESS_FALLBACK_CONTEXT.fieldSources)
  ) {
    for (const source of ADDRESS_FALLBACK_CONTEXT.fieldSources) {
      appendSource(source);
    }
  }

  const rawCandidates = [];
  for (const source of fallbackSources) {
    collectRawAddressCandidatesFromSource(rawCandidates, source);
  }

  if (Array.isArray(options.extraRawCandidates)) {
    for (const candidate of options.extraRawCandidates) {
      const normalized = safeNullIfEmpty(candidate);
      if (normalized) {
        rawCandidates.push(normalized);
      }
    }
  }

  if (
    ADDRESS_FALLBACK_CONTEXT &&
    Array.isArray(ADDRESS_FALLBACK_CONTEXT.unnormalizedCandidates)
  ) {
    for (const candidate of ADDRESS_FALLBACK_CONTEXT.unnormalizedCandidates) {
      const normalized = safeNullIfEmpty(candidate);
      if (normalized) {
        rawCandidates.push(normalized);
      }
    }
  }

  const resolvedRaw = pickFirstMeaningfulString(rawCandidates);
  if (!resolvedRaw) {
    removeFileIfExists(addressPath);
    if (
      Array.isArray(options.relationshipDirectories) &&
      options.relationshipDirectories.length
    ) {
      enforceRestrictedRelationshipNullOutputs(options.relationshipDirectories);
    }
    return;
  }

  const requestIdentifierCandidates = [];
  const appendRequestIdentifierCandidate = (value) => {
    const normalized = safeNullIfEmpty(value);
    if (normalized) {
      requestIdentifierCandidates.push(normalized);
    }
  };

  for (const source of fallbackSources) {
    if (!source || typeof source !== "object") continue;
    appendRequestIdentifierCandidate(source.request_identifier);
  }

  if (
    ADDRESS_FALLBACK_CONTEXT &&
    Array.isArray(ADDRESS_FALLBACK_CONTEXT.requestIdentifierCandidates)
  ) {
    for (const candidate of ADDRESS_FALLBACK_CONTEXT.requestIdentifierCandidates) {
      appendRequestIdentifierCandidate(candidate);
    }
  }

  if (Array.isArray(options.requestIdentifierCandidates)) {
    for (const candidate of options.requestIdentifierCandidates) {
      appendRequestIdentifierCandidate(candidate);
    }
  }

  const payload = { unnormalized_address: resolvedRaw };
  const resolvedRequestIdentifier = pickFirstMeaningfulString(
    requestIdentifierCandidates,
  );
  if (resolvedRequestIdentifier) {
    payload.request_identifier = resolvedRequestIdentifier;
  }

  writeJSON(addressPath, payload);

  if (
    Array.isArray(options.relationshipDirectories) &&
    options.relationshipDirectories.length
  ) {
    enforceRestrictedRelationshipNullOutputs(options.relationshipDirectories);
  }
}

function padGridValue(value, length) {
  const cleaned = safeNullIfEmpty(value);
  if (!cleaned) return null;
  const alphanumeric = cleaned.replace(/\s+/g, "");
  if (!alphanumeric) return null;
  if (/^[0-9]+$/.test(alphanumeric)) {
    return alphanumeric.padStart(length, "0");
  }
  return alphanumeric;
}

function parseGridFromPcn(rawValue) {
  if (!rawValue) return null;
  const digits = String(rawValue).replace(/[^0-9]/g, "");
  if (digits.length !== 17) return null;

  const township = digits.slice(2, 4);
  const range = digits.slice(4, 6);
  const section = digits.slice(6, 8);
  const block = digits.slice(10, 13);
  const lot = digits.slice(13);

  if (![township, range, section].every((part) => /^[0-9]{2}$/.test(part))) {
    return null;
  }

  return {
    township,
    range,
    section,
    block: /^[0-9]{3}$/.test(block) ? block : null,
    lot: /^[0-9]{4}$/.test(lot) ? lot : null,
  };
}

function extractPostalPieces(raw) {
  if (!raw) {
    return { postal: null, plus4: null };
  }

  const matches = Array.from(
    String(raw).matchAll(/\b(\d{5})(?:[-\s]?(\d{4}))?\b/g),
  );
  if (!matches.length) {
    return { postal: null, plus4: null };
  }

  const [, postal, plus4] = matches[matches.length - 1];
  return {
    postal: postal || null,
    plus4: plus4 || null,
  };
}

function coerceEmptyStringsToNull(obj, fields) {
  if (!obj || typeof obj !== "object") return;
  const keys =
    Array.isArray(fields) && fields.length ? fields : Object.keys(obj);
  for (const key of keys) {
    if (!Object.prototype.hasOwnProperty.call(obj, key)) continue;
    const value = obj[key];
    if (typeof value === "string") {
      const trimmed = value.trim();
      obj[key] = trimmed.length ? trimmed : null;
    }
  }
}

function deepClone(value) {
  if (value === null || value === undefined) return value;
  try {
    return JSON.parse(JSON.stringify(value));
  } catch (err) {
    return null;
  }
}

async function fetchParcelCentroid(parcelId) {
  if (process && process.env && process.env.DISABLE_PARCEL_CENTROID === "1") {
    return null;
  }
  const normalized =
    typeof parcelId === "string"
      ? normalizeParcelIdentifierForFetch(parcelId)
      : null;
  if (!normalized) return null;

  const body = new URLSearchParams({
    functionName: "getPolyByPCN",
    parameters: JSON.stringify({ pcn: normalized }),
  });

  try {
    const response = await fetch("https://maps.co.palm-beach.fl.us/giswebapi/gisdata", {
      method: "POST",
      headers: {
        "content-type": "application/x-www-form-urlencoded",
      },
      body: body.toString(),
    });
    if (!response.ok) return null;

    const text = await response.text();
    if (!text) return null;

    let payload;
    try {
      payload = JSON.parse(text);
      if (typeof payload === "string") {
        payload = JSON.parse(payload);
      }
    } catch (err) {
      return null;
    }
    if (!payload || typeof payload.point !== "string") return null;

    const [lonStr, latStr] = payload.point.split(",").map((segment) => segment.trim());
    const latitude = Number(latStr);
    const longitude = Number(lonStr);
    if (!Number.isFinite(latitude) || !Number.isFinite(longitude)) return null;

    return { latitude, longitude };
  } catch (err) {
    return null;
  }
}

async function ensureAddressCoordinates(addressFilePath, options = {}) {
  if (!addressFilePath || !fs.existsSync(addressFilePath)) {
    return;
  }

  let payload;
  try {
    payload = readJSON(addressFilePath);
  } catch {
    return;
  }

  if (!payload || typeof payload !== "object" || Array.isArray(payload)) {
    return;
  }

  const hasLatitude = Number.isFinite(parseCoordinate(payload.latitude));
  const hasLongitude = Number.isFinite(parseCoordinate(payload.longitude));
  if (hasLatitude && hasLongitude) {
    return;
  }

  const tryApplyCoordinates = (candidate) => {
    if (!candidate || typeof candidate !== "object") return false;
    const latitude = parseCoordinate(candidate.latitude);
    const longitude = parseCoordinate(candidate.longitude);
    if (!Number.isFinite(latitude) || !Number.isFinite(longitude)) return false;
    payload.latitude = latitude;
    payload.longitude = longitude;
    return true;
  };

  const enqueue = (queue, candidate) => {
    if (!candidate) return;
    if (Array.isArray(candidate)) {
      candidate.forEach((entry) => enqueue(queue, entry));
      return;
    }
    queue.push(candidate);
  };

  const coordinateQueue = [];
  enqueue(coordinateQueue, options.coordinateCandidates);
  if (
    ADDRESS_FALLBACK_CONTEXT &&
    Array.isArray(ADDRESS_FALLBACK_CONTEXT.coordinateCandidates)
  ) {
    enqueue(coordinateQueue, ADDRESS_FALLBACK_CONTEXT.coordinateCandidates);
  }

  for (const candidate of coordinateQueue) {
    if (tryApplyCoordinates(candidate)) {
      fs.writeFileSync(addressFilePath, JSON.stringify(payload, null, 2));
      return;
    }
  }

  const parcelQueue = [];
  const enqueueParcelCandidate = (value) => {
    if (!value) return;
    if (Array.isArray(value)) {
      value.forEach(enqueueParcelCandidate);
      return;
    }
    const normalized = normalizeParcelIdentifierForFetch(value);
    if (normalized) {
      parcelQueue.push(normalized);
    }
  };

  enqueueParcelCandidate(options.parcelIdCandidates);
  if (
    ADDRESS_FALLBACK_CONTEXT &&
    Array.isArray(ADDRESS_FALLBACK_CONTEXT.parcelIdCandidates)
  ) {
    enqueueParcelCandidate(ADDRESS_FALLBACK_CONTEXT.parcelIdCandidates);
  }

  for (const parcelId of parcelQueue) {
    try {
      const centroid = await fetchParcelCentroid(parcelId);
      if (tryApplyCoordinates(centroid)) {
        fs.writeFileSync(addressFilePath, JSON.stringify(payload, null, 2));
        return;
      }
    } catch {
      // Fall through to other recovery strategies when centroid lookup fails.
    }
  }

  const addressCandidates = [];
  const enqueueAddressCandidate = (value) => {
    if (!value) return;
    if (Array.isArray(value)) {
      value.forEach(enqueueAddressCandidate);
      return;
    }
    const normalized = normalizeWhitespace(value);
    if (normalized) {
      addressCandidates.push(normalized);
    }
  };

  enqueueAddressCandidate(options.addressCandidates);
  enqueueAddressCandidate(payload.unnormalized_address);
  enqueueAddressCandidate(composeUnnormalizedAddress(payload));
  if (
    ADDRESS_FALLBACK_CONTEXT &&
    Array.isArray(ADDRESS_FALLBACK_CONTEXT.unnormalizedCandidates)
  ) {
    enqueueAddressCandidate(ADDRESS_FALLBACK_CONTEXT.unnormalizedCandidates);
  }

  if (!addressCandidates.length) {
    return;
  }

  const cityHints = collectNonEmptyStrings(
    payload.city_name,
    payload.municipality_name,
    options.cityHints || [],
  );
  const municipalityHints = collectNonEmptyStrings(
    payload.municipality_name,
    options.municipalityHints || [],
  );
  const countyHints = collectNonEmptyStrings(
    payload.county_name,
    options.countyHints || [],
  );
  const stateHints = collectNonEmptyStrings(
    payload.state_code,
    options.stateHints || [],
  );
  if (!stateHints.length) {
    stateHints.push("FL");
  }
  const postalHints = collectNonEmptyStrings(
    payload.postal_code,
    payload.plus_four_postal_code,
    options.postalHints || [],
  );

  for (const candidate of addressCandidates) {
    const geocodeResult = await geocodeAddressWithFallbacks({
      primaryQuery: candidate,
      address: payload,
      cityHints,
      municipalityHints,
      countyHints,
      stateHints,
      postalHints,
    });
    if (tryApplyCoordinates(geocodeResult)) {
      fs.writeFileSync(addressFilePath, JSON.stringify(payload, null, 2));
      return;
    }
  }
}

async function finalizeAddressVariantOutput(addressFilePath, options = {}) {
  const {
    unnormalizedPath = "unnormalized_address.json",
    seedPath = "property_seed.json",
    rawCandidates = [],
    coordinateCandidates = [],
    parcelIdCandidates = [],
    requestIdentifierCandidates = [],
    sourceHttpRequestCandidates = [],
    addressCandidates = [],
    cityCandidates = [],
    municipalityCandidates = [],
    countyCandidates = [],
    stateCandidates = [],
    postalCandidates = [],
    plus4Candidates = [],
    preferRawWhenAvailable = true,
  } = options || {};

  if (!addressFilePath || !fs.existsSync(addressFilePath)) {
    return;
  }

  const payload = readJSONIfExists(addressFilePath);
  if (!payload || typeof payload !== "object" || Array.isArray(payload)) {
    return;
  }

  const unnormalizedSource = readJSONIfExists(unnormalizedPath);
  const seedSource = readJSONIfExists(seedPath);

  const normalizedSurface =
    ensureAddressOutputFieldPresence({ ...payload }) || { ...payload };

  const rawQueue = [];
  const pushRawCandidate = (value) => {
    if (value === undefined || value === null) return;
    if (Array.isArray(value)) {
      value.forEach(pushRawCandidate);
      return;
    }
    if (typeof value !== "string") return;
    const trimmed = value.trim();
    if (trimmed.length) {
      rawQueue.push(trimmed);
    }
  };

  pushRawCandidate(normalizedSurface.unnormalized_address);
  pushRawCandidate(rawCandidates);
  pushRawCandidate(addressCandidates);

  const enqueueRawSourceFields = (source) => {
    if (!source || typeof source !== "object") return;
    const fields = [
      "unnormalized_address",
      "full_address",
      "site_address",
      "address",
      "raw_address",
      "location_address",
      "mail_address",
    ];
    for (const field of fields) {
      pushRawCandidate(source[field]);
    }
    if (Array.isArray(source.lines)) {
      const joined = source.lines
        .map((line) => (typeof line === "string" ? line.trim() : ""))
        .filter(Boolean)
        .join(", ");
      pushRawCandidate(joined);
    }
  };

  enqueueRawSourceFields(unnormalizedSource);
  enqueueRawSourceFields(seedSource);

  const resolvedRaw =
    resolveFirstNonEmptyString(rawQueue) ||
    (typeof composeFallbackUnnormalizedAddressFromFields === "function"
      ? composeFallbackUnnormalizedAddressFromFields({ ...normalizedSurface })
      : null);

  const normalizedProbe =
    ensureAddressOutputFieldPresence({ ...normalizedSurface }) ||
    { ...normalizedSurface };
  const hasStructuredCoverage =
    typeof hasStructuredAddressCoverage === "function"
      ? hasStructuredAddressCoverage({ ...normalizedProbe })
      : false;

  const coordinateHints = [];
  const pushCoordinateCandidate = (candidate) => {
    if (!candidate || typeof candidate !== "object") return;
    const latitude = parseCoordinate(candidate.latitude);
    const longitude = parseCoordinate(candidate.longitude);
    if (Number.isFinite(latitude) && Number.isFinite(longitude)) {
      coordinateHints.push({ latitude, longitude });
    }
  };

  pushCoordinateCandidate(payload);
  pushCoordinateCandidate(normalizedSurface);
  pushCoordinateCandidate(unnormalizedSource);
  pushCoordinateCandidate(seedSource);
  if (Array.isArray(coordinateCandidates)) {
    coordinateCandidates.forEach(pushCoordinateCandidate);
  }

  const parcelHints = [];
  const pushParcelCandidate = (candidate) => {
    if (!candidate) return;
    if (Array.isArray(candidate)) {
      candidate.forEach(pushParcelCandidate);
      return;
    }
    const normalized = normalizeParcelIdentifierForFetch(candidate);
    if (normalized) {
      parcelHints.push(normalized);
    }
  };
  pushParcelCandidate(parcelIdCandidates);
  if (seedSource && seedSource.parcel_id) {
    pushParcelCandidate(seedSource.parcel_id);
  }
  if (unnormalizedSource && unnormalizedSource.parcel_id) {
    pushParcelCandidate(unnormalizedSource.parcel_id);
  }

  const combinedRequestIdentifierCandidates = [
    normalizedSurface.request_identifier,
    payload.request_identifier,
    ...(Array.isArray(requestIdentifierCandidates)
      ? requestIdentifierCandidates
      : []),
    unnormalizedSource && unnormalizedSource.request_identifier,
    seedSource && seedSource.request_identifier,
  ];

  const combinedSourceHttpCandidates = [
    normalizedSurface.source_http_request,
    payload.source_http_request,
    ...(Array.isArray(sourceHttpRequestCandidates)
      ? sourceHttpRequestCandidates
      : []),
    unnormalizedSource && unnormalizedSource.source_http_request,
    seedSource && seedSource.source_http_request,
  ];

  const requestIdentifier = resolveRequestIdentifierCandidate(
    combinedRequestIdentifierCandidates,
  );
  const sourceHttp = resolveSourceHttpRequestCandidate(
    combinedSourceHttpCandidates,
  );

  const shouldEmitRaw =
    resolvedRaw &&
    (preferRawWhenAvailable || !hasStructuredCoverage);

  if (shouldEmitRaw && resolvedRaw) {
    const rawOutput = { ...RAW_ADDRESS_SCHEMA_TEMPLATE };
    for (const field of RAW_ADDRESS_OUTPUT_FIELDS) {
      const sanitized = sanitizeAddressFieldValue(
        field,
        normalizedSurface[field],
      );
      rawOutput[field] =
        sanitized === undefined || sanitized === null ? null : sanitized;
    }
    rawOutput.unnormalized_address = resolvedRaw;
    if (!rawOutput.postal_code) {
      rawOutput.plus_four_postal_code = null;
    }
    if (rawOutput.state_code && !rawOutput.country_code) {
      rawOutput.country_code = "US";
    }
    if (!Number.isFinite(rawOutput.latitude) || !Number.isFinite(rawOutput.longitude)) {
      const fallbackCoordinate = coordinateHints.find(
        (candidate) =>
          candidate &&
          Number.isFinite(candidate.latitude) &&
          Number.isFinite(candidate.longitude),
      );
      if (fallbackCoordinate) {
        rawOutput.latitude = fallbackCoordinate.latitude;
        rawOutput.longitude = fallbackCoordinate.longitude;
      }
    }
    if (
      (rawOutput.latitude == null && rawOutput.longitude !== null) ||
      (rawOutput.latitude !== null && rawOutput.longitude == null)
    ) {
      rawOutput.latitude = null;
      rawOutput.longitude = null;
    }
    if (requestIdentifier !== undefined) {
      rawOutput.request_identifier =
        requestIdentifier === null ? null : requestIdentifier;
    } else if (
      Object.prototype.hasOwnProperty.call(rawOutput, "request_identifier")
    ) {
      rawOutput.request_identifier = null;
    }
    if (sourceHttp) {
      rawOutput.source_http_request = deepClone(sourceHttp);
    } else if (
      Object.prototype.hasOwnProperty.call(
        rawOutput,
        "source_http_request",
      )
    ) {
      rawOutput.source_http_request = null;
    }
    const surfacedRaw =
      ensureAddressOutputFieldPresence({ ...rawOutput }) || { ...rawOutput };
    const sanitizedRaw =
      stripAddressRequestMetadata({ ...surfacedRaw }) || { ...surfacedRaw };
    if (
      Object.prototype.hasOwnProperty.call(
        sanitizedRaw,
        "__force_raw_variant",
      )
    ) {
      delete sanitizedRaw.__force_raw_variant;
    }
    fs.writeFileSync(
      addressFilePath,
      JSON.stringify(sanitizedRaw, null, 2),
    );
    return;
  }

  if (!hasStructuredCoverage) {
    return;
  }

  const normalizedOutput = { ...NORMALIZED_ADDRESS_SCHEMA_TEMPLATE };
  for (const field of NORMALIZED_ADDRESS_FIELDS) {
    const sanitized = sanitizeAddressFieldValue(
      field,
      normalizedSurface[field],
    );
    normalizedOutput[field] =
      sanitized === undefined || sanitized === null ? null : sanitized;
  }
  if (!normalizedOutput.postal_code) {
    normalizedOutput.plus_four_postal_code = null;
  }
  if (normalizedOutput.state_code && !normalizedOutput.country_code) {
    normalizedOutput.country_code = "US";
  }
  if (requestIdentifier !== undefined) {
    normalizedOutput.request_identifier =
      requestIdentifier === null ? null : requestIdentifier;
  } else if (
    Object.prototype.hasOwnProperty.call(
      normalizedOutput,
      "request_identifier",
    )
  ) {
    normalizedOutput.request_identifier = null;
  }
  normalizedOutput.source_http_request = sourceHttp
    ? deepClone(sourceHttp)
    : null;
  if (
    Object.prototype.hasOwnProperty.call(
      normalizedOutput,
      "unnormalized_address",
    )
  ) {
    delete normalizedOutput.unnormalized_address;
  }
  const surfacedNormalized =
    ensureAddressOutputFieldPresence({ ...normalizedOutput }) ||
    { ...normalizedOutput };
  const sanitizedNormalized =
    stripAddressRequestMetadata({ ...surfacedNormalized }) ||
    { ...surfacedNormalized };
  fs.writeFileSync(
    addressFilePath,
    JSON.stringify(sanitizedNormalized, null, 2),
  );
}

function enforceAddressVariantOrRawFallback(addressPath, options = {}) {
  if (!addressPath) {
    return;
  }

  const {
    unnormalizedPath = "unnormalized_address.json",
    seedPath = "property_seed.json",
    defaultCountyName = null,
    defaultStateCode = null,
    defaultCountryCode = "US",
    extraRawCandidates = [],
  } = options || {};

  const unnormalizedSource = readJSONIfExists(unnormalizedPath);
  const seedSource = readJSONIfExists(seedPath);
  const hasExistingPayload = fs.existsSync(addressPath);
  const existingPayload = readJSONIfExists(addressPath);

  const normalizedSurface =
    existingPayload && typeof existingPayload === "object"
      ? ensureAddressOutputFieldPresence({ ...existingPayload }) ||
        { ...existingPayload }
      : {};

  const resolveFlattenedStrings = (...sources) =>
    resolveFirstNonEmptyString(flattenCandidateValues(...sources));

  const requestIdentifier = safeNullIfEmpty(
    resolveFlattenedStrings(
      normalizedSurface.request_identifier,
      existingPayload && existingPayload.request_identifier,
      unnormalizedSource && unnormalizedSource.request_identifier,
      seedSource && seedSource.request_identifier,
    ),
  );

  const sourceHttpRequest = resolveSourceHttpRequestCandidate(
    normalizedSurface.source_http_request,
    existingPayload && existingPayload.source_http_request,
    unnormalizedSource && unnormalizedSource.source_http_request,
    seedSource && seedSource.source_http_request,
  );

  const hasStructuredCoverage =
    hasStructuredAddressCoverage &&
    typeof hasStructuredAddressCoverage === "function"
      ? hasStructuredAddressCoverage({ ...normalizedSurface })
      : false;

  if (hasStructuredCoverage) {
    const normalizedOutput =
      buildNormalizedAddressOutputForSchema({ ...normalizedSurface }) || null;
    if (normalizedOutput) {
      if (!normalizedOutput.postal_code) {
        normalizedOutput.plus_four_postal_code = null;
      }
      if (
        hasMeaningfulAddressValue(normalizedOutput.state_code) &&
        !hasMeaningfulAddressValue(normalizedOutput.country_code)
      ) {
        normalizedOutput.country_code = (defaultCountryCode || "US").toUpperCase();
      }
      const finalRequestIdentifier = safeNullIfEmpty(
        resolveFirstNonEmptyString(
          flattenCandidateValues(
            requestIdentifier,
            normalizedSurface.request_identifier,
            existingPayload && existingPayload.request_identifier,
            unnormalizedSource && unnormalizedSource.request_identifier,
            seedSource && seedSource.request_identifier,
          ),
        ),
      );
      if (finalRequestIdentifier !== undefined) {
        normalizedOutput.request_identifier =
          finalRequestIdentifier === null ? null : finalRequestIdentifier;
      }
      const finalSourceHttpRequest = resolveSourceHttpRequestCandidate(
        sourceHttpRequest,
        normalizedSurface.source_http_request,
        existingPayload && existingPayload.source_http_request,
        unnormalizedSource && unnormalizedSource.source_http_request,
        seedSource && seedSource.source_http_request,
      );
      normalizedOutput.source_http_request = finalSourceHttpRequest
        ? deepClone(prepareSourceHttpRequest(finalSourceHttpRequest))
        : null;
      const surfaced =
        ensureAddressOutputFieldPresence(normalizedOutput) || normalizedOutput;
      const sanitized = stripAddressRequestMetadata(surfaced) || surfaced;
      if (finalRequestIdentifier !== undefined) {
        sanitized.request_identifier =
          finalRequestIdentifier === null ? null : finalRequestIdentifier;
      } else if (
        Object.prototype.hasOwnProperty.call(sanitized, "request_identifier")
      ) {
        delete sanitized.request_identifier;
      }
      if (finalSourceHttpRequest) {
        sanitized.source_http_request = deepClone(
          prepareSourceHttpRequest(finalSourceHttpRequest),
        );
      } else if (
        Object.prototype.hasOwnProperty.call(sanitized, "source_http_request")
      ) {
        delete sanitized.source_http_request;
      }
      const serialized = JSON.stringify(sanitized, null, 2);
      ensureDir(path.dirname(addressPath));
      fs.writeFileSync(addressPath, serialized);
      return;
    }
  }

  const rawCandidates = [
    normalizedSurface.unnormalized_address,
    existingPayload && existingPayload.unnormalized_address,
    typeof composeUnnormalizedAddress === "function"
      ? composeUnnormalizedAddress(normalizedSurface)
      : null,
  ];

  if (
    ADDRESS_FALLBACK_CONTEXT &&
    Array.isArray(ADDRESS_FALLBACK_CONTEXT.unnormalizedCandidates)
  ) {
    rawCandidates.push(...ADDRESS_FALLBACK_CONTEXT.unnormalizedCandidates);
  }

  if (
    ADDRESS_FALLBACK_CONTEXT &&
    Array.isArray(ADDRESS_FALLBACK_CONTEXT.fieldSources)
  ) {
    for (const source of ADDRESS_FALLBACK_CONTEXT.fieldSources) {
      if (!source || typeof source !== "object") continue;
      rawCandidates.push(source.unnormalized_address, source.full_address);
    }
  }

  if (Array.isArray(extraRawCandidates)) {
    rawCandidates.push(...extraRawCandidates);
  }

  if (unnormalizedSource && typeof unnormalizedSource === "object") {
    rawCandidates.push(
      unnormalizedSource.unnormalized_address,
      unnormalizedSource.full_address,
    );
    if (
      Array.isArray(unnormalizedSource.lines) &&
      unnormalizedSource.lines.length
    ) {
      rawCandidates.push(
        unnormalizedSource.lines
          .map((line) => (typeof line === "string" ? line.trim() : ""))
          .filter(Boolean)
          .join(", "),
      );
    }
  }

  if (seedSource && typeof seedSource === "object") {
    rawCandidates.push(seedSource.unnormalized_address, seedSource.full_address);
  }

  const resolvedRaw = resolveFirstNonEmptyString(
    flattenCandidateValues(rawCandidates),
  );
  if (!resolvedRaw) {
    if (hasExistingPayload) {
      removeFileIfExists(addressPath);
    }
    return;
  }

  const rawPayload =
    buildRawAddressOneOfPayload(
      resolvedRaw,
      requestIdentifier === undefined ? null : requestIdentifier,
      sourceHttpRequest,
      normalizedSurface,
    ) || null;

  if (!rawPayload) {
    if (hasExistingPayload) {
      removeFileIfExists(addressPath);
    }
    return;
  }

  const applyFallback = (field, values) => {
    if (hasMeaningfulAddressValue(rawPayload[field])) {
      return;
    }
    const flattened = flattenCandidateValues(values);
    if (!flattened.length) {
      return;
    }
    const resolvedValue = ADDRESS_COORDINATE_FIELDS.includes(field)
      ? resolveFirstCoordinate(flattened)
      : resolveFieldFromCandidates(field, flattened);
    if (resolvedValue === undefined || resolvedValue === null) {
      return;
    }
    rawPayload[field] = resolvedValue;
  };

  applyFallback("county_name", [
    normalizedSurface.county_name,
    existingPayload && existingPayload.county_name,
    unnormalizedSource &&
      (unnormalizedSource.county_name || unnormalizedSource.county_jurisdiction),
    seedSource && seedSource.county_name,
    defaultCountyName,
  ]);

  applyFallback("state_code", [
    normalizedSurface.state_code,
    existingPayload && existingPayload.state_code,
    unnormalizedSource && unnormalizedSource.state_code,
    seedSource && seedSource.state_code,
    defaultStateCode,
  ]);

  applyFallback("city_name", [
    normalizedSurface.city_name,
    existingPayload && existingPayload.city_name,
    unnormalizedSource && unnormalizedSource.city_name,
    seedSource && seedSource.city_name,
  ]);

  applyFallback("municipality_name", [
    normalizedSurface.municipality_name,
    existingPayload && existingPayload.municipality_name,
    unnormalizedSource && unnormalizedSource.municipality_name,
  ]);

  applyFallback("postal_code", [
    normalizedSurface.postal_code,
    existingPayload && existingPayload.postal_code,
    unnormalizedSource && unnormalizedSource.postal_code,
    seedSource && seedSource.postal_code,
  ]);

  applyFallback("plus_four_postal_code", [
    normalizedSurface.plus_four_postal_code,
    existingPayload && existingPayload.plus_four_postal_code,
    unnormalizedSource && unnormalizedSource.plus_four_postal_code,
    seedSource && seedSource.plus_four_postal_code,
  ]);

  if (!rawPayload.postal_code) {
    rawPayload.plus_four_postal_code = null;
  }

  if (
    hasMeaningfulAddressValue(rawPayload.state_code) &&
    !hasMeaningfulAddressValue(rawPayload.country_code)
  ) {
    rawPayload.country_code = (defaultCountryCode || "US").toUpperCase();
  } else if (
    !hasMeaningfulAddressValue(rawPayload.country_code) &&
    defaultCountryCode
  ) {
    rawPayload.country_code = (defaultCountryCode || "US").toUpperCase();
  }

  const latitude = parseCoordinate(rawPayload.latitude);
  const longitude = parseCoordinate(rawPayload.longitude);
  if (Number.isFinite(latitude) && Number.isFinite(longitude)) {
    rawPayload.latitude = latitude;
    rawPayload.longitude = longitude;
  } else {
    rawPayload.latitude = null;
    rawPayload.longitude = null;
  }

  const finalRequestIdentifier = safeNullIfEmpty(
    resolveFirstNonEmptyString(
      flattenCandidateValues(
        requestIdentifier,
        normalizedSurface.request_identifier,
        existingPayload && existingPayload.request_identifier,
        unnormalizedSource && unnormalizedSource.request_identifier,
        seedSource && seedSource.request_identifier,
      ),
    ),
  );
  if (finalRequestIdentifier !== undefined) {
    rawPayload.request_identifier =
      finalRequestIdentifier === null ? null : finalRequestIdentifier;
  }

  const finalSourceHttpRequest = resolveSourceHttpRequestCandidate(
    sourceHttpRequest,
    normalizedSurface.source_http_request,
    existingPayload && existingPayload.source_http_request,
    unnormalizedSource && unnormalizedSource.source_http_request,
    seedSource && seedSource.source_http_request,
  );
  rawPayload.source_http_request = finalSourceHttpRequest
    ? deepClone(prepareSourceHttpRequest(finalSourceHttpRequest))
    : null;

  const surfacedRaw =
    ensureAddressOutputFieldPresence(rawPayload) || rawPayload;
  const sanitizedRaw = stripAddressRequestMetadata(surfacedRaw) || surfacedRaw;
  if (finalRequestIdentifier !== undefined) {
    sanitizedRaw.request_identifier =
      finalRequestIdentifier === null ? null : finalRequestIdentifier;
  } else if (
    Object.prototype.hasOwnProperty.call(sanitizedRaw, "request_identifier")
  ) {
    sanitizedRaw.request_identifier = null;
  }
  if (finalSourceHttpRequest) {
    sanitizedRaw.source_http_request = deepClone(
      prepareSourceHttpRequest(finalSourceHttpRequest),
    );
  } else if (
    Object.prototype.hasOwnProperty.call(sanitizedRaw, "source_http_request")
  ) {
    sanitizedRaw.source_http_request = null;
  }
  const serialized = JSON.stringify(sanitizedRaw, null, 2);
  ensureDir(path.dirname(addressPath));
  fs.writeFileSync(addressPath, serialized);
}

function getGeocodeUserAgent() {
  const fromEnv =
    process &&
    process.env &&
    typeof process.env.NOMINATIM_USER_AGENT === "string" &&
    process.env.NOMINATIM_USER_AGENT.trim().length
      ? process.env.NOMINATIM_USER_AGENT.trim()
      : null;
  if (fromEnv) return fromEnv;
  return "ElephantCountyTransform/1.0 (transform@elephant.ai)";
}

async function geocodeAddress(addressText) {
  const query =
    typeof addressText === "string" ? addressText.trim() : "";
  if (!query.length) {
    return null;
  }

  const nominatimResult = await geocodeAddressWithNominatim(query);
  if (nominatimResult) {
    return nominatimResult;
  }

  return geocodeAddressWithCensus(query);
}

async function geocodeAddressWithNominatim(query) {
  const searchParams = new URLSearchParams({
    q: query,
    format: "jsonv2",
    addressdetails: "1",
    limit: "1",
  });

  try {
    const response = await fetch(
      `https://nominatim.openstreetmap.org/search?${searchParams.toString()}`,
      {
        method: "GET",
        headers: {
          "user-agent": getGeocodeUserAgent(),
          accept: "application/json",
        },
      },
    );

    if (!response.ok) {
      return null;
    }

    const payload = await response.json();
    if (!Array.isArray(payload) || payload.length === 0) {
      return null;
    }

    const first = payload[0];
    if (!first) return null;
    const latitude = Number(first.lat);
    const longitude = Number(first.lon);
    if (!Number.isFinite(latitude) || !Number.isFinite(longitude)) {
      return null;
    }
    const components =
      first.address && typeof first.address === "object"
        ? first.address
        : {};

    const postalCandidate =
      typeof first.postcode === "string" && first.postcode.trim().length
        ? first.postcode.trim()
        : typeof components.postcode === "string" && components.postcode.trim().length
          ? components.postcode.trim()
          : null;

    return {
      latitude,
      longitude,
      components,
      postalCode: postalCandidate,
      displayName:
        typeof first.display_name === "string" ? first.display_name.trim() : null,
    };
  } catch (error) {
    return null;
  }
}

function collectNonEmptyStrings(...values) {
  const flattened = values.flat();
  const seen = new Set();
  const results = [];
  for (const candidate of flattened) {
    if (candidate === undefined || candidate === null) continue;
    let raw = candidate;
    if (typeof raw !== "string") {
      if (typeof raw === "number" && Number.isFinite(raw)) {
        raw = String(raw);
      } else {
        continue;
      }
    }
    const normalized = normalizeWhitespace(raw);
    if (!normalized) continue;
    const key = normalized.toUpperCase();
    if (seen.has(key)) continue;
    seen.add(key);
    results.push(normalized);
  }
  return results;
}

function composeStreetLineForGeocode(address) {
  if (!address || typeof address !== "object") return null;
  const segments = [];
  const pushSegment = (value) => {
    if (value === undefined || value === null) return;
    const normalized = normalizeWhitespace(value);
    if (!normalized) return;
    segments.push(normalized);
  };

  pushSegment(address.street_number);
  pushSegment(address.street_pre_directional_text);
  pushSegment(address.street_name);
  pushSegment(address.street_suffix_type);
  pushSegment(address.street_post_directional_text);

  if (
    Object.prototype.hasOwnProperty.call(address, "unit_identifier") &&
    address.unit_identifier !== undefined &&
    address.unit_identifier !== null
  ) {
    const unitSegment = normalizeWhitespace(address.unit_identifier);
    if (unitSegment) {
      segments.push(`#${unitSegment}`);
    }
  }

  return segments.length ? segments.join(" ") : null;
}

async function geocodeAddressWithFallbacks(options = {}) {
  const {
    primaryQuery = null,
    address = null,
    cityHints = [],
    municipalityHints = [],
    countyHints = [],
    stateHints = [],
    postalHints = [],
  } = options;

  const queries = [];
  const seenQueries = new Set();
  const enqueueQuery = (candidate) => {
    if (candidate === undefined || candidate === null) return;
    const normalized = normalizeWhitespace(candidate);
    if (!normalized) return;
    const key = normalized.toUpperCase();
    if (seenQueries.has(key)) return;
    seenQueries.add(key);
    queries.push(normalized);
  };

  enqueueQuery(primaryQuery);

  const streetLine = composeStreetLineForGeocode(address);
  const stateCandidates = collectNonEmptyStrings(stateHints);
  if (!stateCandidates.length) {
    stateCandidates.push("FL");
  }
  const cityCandidates = collectNonEmptyStrings(cityHints, municipalityHints);
  const countyCandidates = collectNonEmptyStrings(countyHints).map((county) =>
    county.toUpperCase().includes("COUNTY") ? county : `${county} County`,
  );
  const postalCandidates = collectNonEmptyStrings(postalHints);

  if (primaryQuery) {
    for (const state of stateCandidates) {
      enqueueQuery(`${primaryQuery}, ${state}`);
    }
    for (const county of countyCandidates) {
      enqueueQuery(`${primaryQuery}, ${county}`);
    }
  }

  if (streetLine) {
    for (const city of cityCandidates) {
      for (const state of stateCandidates) {
        const base = `${streetLine}, ${city}, ${state}`;
        enqueueQuery(base);
        for (const postal of postalCandidates) {
          enqueueQuery(`${base} ${postal}`);
        }
      }
    }

    for (const county of countyCandidates) {
      for (const state of stateCandidates) {
        enqueueQuery(`${streetLine}, ${county}, ${state}`);
      }
    }
  }

  if (cityCandidates.length) {
    for (const city of cityCandidates) {
      for (const state of stateCandidates) {
        enqueueQuery(`${city}, ${state}`);
      }
    }
  }

  if (countyCandidates.length) {
    for (const county of countyCandidates) {
      for (const state of stateCandidates) {
        enqueueQuery(`${county}, ${state}`);
      }
    }
  }

  if (!queries.length) {
    return null;
  }

  for (const query of queries) {
    const result = await geocodeAddress(query);
    if (result) {
      return result;
    }
  }

  return null;
}

async function geocodeAddressWithCensus(query) {
  const params = new URLSearchParams({
    address: query,
    benchmark: "2020",
    format: "json",
  });

  try {
    const response = await fetch(
      `https://geocoding.geo.census.gov/geocoder/locations/onelineaddress?${params.toString()}`,
      {
        method: "GET",
        headers: {
          "user-agent": getGeocodeUserAgent(),
          accept: "application/json",
        },
      },
    );

    if (!response.ok) {
      return null;
    }

    const payload = await response.json();
    const matches =
      payload &&
      payload.result &&
      Array.isArray(payload.result.addressMatches)
        ? payload.result.addressMatches
        : [];

    if (!matches.length) {
      return null;
    }

    const match = matches[0];
    if (!match || !match.coordinates) return null;

    const longitude = Number(match.coordinates.x);
    const latitude = Number(match.coordinates.y);
    if (!Number.isFinite(latitude) || !Number.isFinite(longitude)) {
      return null;
    }

    const components =
      match.addressComponents && typeof match.addressComponents === "object"
        ? {
            ...match.addressComponents,
            // Align naming with Nominatim style for downstream handling
            city: match.addressComponents.city || match.addressComponents.placeName || "",
            state_code: match.addressComponents.state || "",
            road: [
              match.addressComponents.preDirection,
              match.addressComponents.streetName,
              match.addressComponents.suffixType,
              match.addressComponents.suffixDirection,
            ]
              .filter(Boolean)
              .join(" ")
              .trim(),
            house_number:
              match.addressComponents.fromAddress ||
              match.addressComponents.toAddress ||
              match.addressComponents.houseNumber ||
              "",
          }
        : {};

    const postal =
      match.addressComponents && match.addressComponents.zip
        ? match.addressComponents.zip
        : null;

    return {
      latitude,
      longitude,
      components,
      postalCode: postal,
      displayName: match.matchedAddress || null,
    };
  } catch (error) {
    return null;
  }
}

function applyGeocodeEnhancements(address, geocodeResult) {
  if (!address || typeof address !== "object") return;
  if (!geocodeResult || typeof geocodeResult !== "object") return;

  const { latitude, longitude, components, postalCode } = geocodeResult;

  if (Number.isFinite(latitude) && !Number.isFinite(address.latitude)) {
    address.latitude = latitude;
  }
  if (Number.isFinite(longitude) && !Number.isFinite(address.longitude)) {
    address.longitude = longitude;
  }

  const componentValue = (keys) => {
    if (!components || typeof components !== "object") return null;
    for (const key of keys) {
      if (
        Object.prototype.hasOwnProperty.call(components, key) &&
        typeof components[key] === "string"
      ) {
        const trimmed = components[key].trim();
        if (trimmed.length) return trimmed;
      }
    }
    return null;
  };

  if (!address.city_name) {
    const cityCandidate = componentValue([
      "city",
      "town",
      "village",
      "hamlet",
      "municipality",
      "locality",
    ]);
    if (cityCandidate) {
      const sanitized = sanitizeCityName(cityCandidate);
      if (sanitized) address.city_name = sanitized;
    }
  }

  if (!address.municipality_name) {
    const municipality =
      componentValue(["municipality", "city", "town", "village"]) || null;
    if (municipality) {
      const titled = toTitleCase(municipality);
      if (titled) address.municipality_name = titled;
    }
  }

  if (!address.state_code) {
    const stateCode = componentValue(["state_code", "ISO3166-2-lvl4"]);
    if (stateCode) {
      address.state_code = stateCode.toUpperCase();
    } else {
      const stateName = componentValue(["state"]);
      if (stateName) {
        const abbrev = stateName.length === 2 ? stateName : null;
        if (abbrev) {
          address.state_code = abbrev.toUpperCase();
        }
      }
    }
  }

  if (!address.country_code) {
    const countryCode = componentValue(["country_code"]);
    if (countryCode) {
      address.country_code = countryCode.toUpperCase();
    }
  }

  if (!address.county_name) {
    const county = componentValue(["county"]);
    if (county) {
      const titled = toTitleCase(county);
      if (titled) address.county_name = titled;
    }
  }

  const normalizedPostal =
    typeof postalCode === "string" ? postalCode.replace(/\s+/g, "") : null;
  if (normalizedPostal && normalizedPostal.length >= 5) {
    if (!address.postal_code) {
      address.postal_code = sanitizePostalCode(normalizedPostal);
    }
    if (!address.plus_four_postal_code && normalizedPostal.includes("-")) {
      const plusMatch = normalizedPostal.split("-")[1];
      const sanitized = sanitizePlus4(plusMatch);
      if (sanitized) address.plus_four_postal_code = sanitized;
    }
    if (
      !address.plus_four_postal_code &&
      normalizedPostal.length === 9
    ) {
      const plusCandidate = sanitizePlus4(normalizedPostal.slice(5));
      if (plusCandidate) address.plus_four_postal_code = plusCandidate;
      const base = sanitizePostalCode(normalizedPostal.slice(0, 5));
      if (base && !address.postal_code) address.postal_code = base;
    }
  }

  if (!address.street_number) {
    const houseNumber = componentValue(["house_number"]);
    if (houseNumber) {
      const trimmed = String(houseNumber).trim();
      if (trimmed.length) address.street_number = trimmed;
    }
  }

  if (!address.street_name) {
    const road = componentValue(["road", "residential", "pedestrian", "footway"]);
    if (road) {
      const formatted = formatStreetNameCase(road);
      if (formatted) address.street_name = formatted.toUpperCase();
    }
  }

  if (!address.street_suffix_type && address.street_name) {
    const parts = address.street_name.split(/\s+/).filter(Boolean);
    if (parts.length > 1) {
      const suffixCandidate = parts[parts.length - 1];
      const mapped = mapStreetSuffixType(suffixCandidate);
      if (mapped) {
        address.street_suffix_type = mapped;
        address.street_name = parts.slice(0, -1).join(" ");
      }
    }
  }

  if (!address.street_pre_directional_text) {
    const directional = componentValue(["road_direction"]);
    if (directional) {
      const normalized = directional.trim().toUpperCase();
      if (normalized.length) address.street_pre_directional_text = normalized;
    }
  }

  if (!address.unit_identifier) {
    const unit =
      componentValue(["unit", "house"]) ||
      (geocodeResult.displayName &&
        geocodeResult.displayName.includes("#")
        ? geocodeResult.displayName.split("#").pop()
        : null);
    if (unit) {
      const trimmed = String(unit).trim();
      if (trimmed.length) address.unit_identifier = trimmed;
    }
  }
}

function extractUnitIdentifierFromAddressLines(lines = []) {
  for (const raw of lines) {
    const candidate = safeNullIfEmpty(raw);
    if (!candidate) continue;
    const match =
      candidate.match(/(?:APT|APARTMENT|STE|SUITE|UNIT|BLDG|BUILDING|LOT|SPACE|SPC|TRLR|#)\s*([A-Z0-9-]+)/i);
    if (match && match[1]) {
      return match[1].trim().toUpperCase();
    }
  }
  return null;
}

function cleanStreetCandidate(value) {
  const normalized = normalizeWhitespace(value);
  if (!normalized) return null;

  let candidate = normalized;
  if (/\bP\.?\s*O\.?\s*BOX\b/i.test(candidate) || /\bPOST OFFICE BOX\b/i.test(candidate)) {
    return null;
  }
  if (candidate.includes(",")) {
    const firstSegment = candidate.split(",")[0].trim();
    if (firstSegment) candidate = firstSegment;
  }

  if (/C\/O/i.test(candidate)) {
    const parts = candidate.split(/C\/O/i);
    const after = parts[parts.length - 1].trim();
    if (after) candidate = after;
  }

  return candidate || null;
}

function combineAddressLines(lines = []) {
  const seen = new Set();
  const filtered = [];
  for (const line of lines) {
    const cleaned = safeNullIfEmpty(line);
    if (!cleaned) continue;
    const key = cleaned.toUpperCase();
    if (seen.has(key)) continue;
    seen.add(key);
    filtered.push(cleaned);
  }
  if (!filtered.length) return null;
  return filtered.join(", ");
}

function composeUnnormalizedAddress(address) {
  if (!address) return null;

  const streetPieces = [];
  const number = safeNullIfEmpty(address.street_number);
  if (number) streetPieces.push(number);

  const nameSegments = [
    safeNullIfEmpty(address.street_pre_directional_text),
    safeNullIfEmpty(address.street_name),
    safeNullIfEmpty(address.street_suffix_type),
    safeNullIfEmpty(address.street_post_directional_text),
  ].filter(Boolean);
  if (nameSegments.length) {
    streetPieces.push(nameSegments.join(" "));
  }

  const route = safeNullIfEmpty(address.route_number);
  if (route) streetPieces.push(route);

  let streetLine = streetPieces.join(" ").replace(/\s+/g, " ").trim();
  const unit = safeNullIfEmpty(address.unit_identifier);
  if (unit) {
    streetLine = streetLine ? `${streetLine}, UNIT ${unit}` : `UNIT ${unit}`;
  }

  const localityPieces = [];
  const city = safeNullIfEmpty(address.city_name);
  if (city) localityPieces.push(city);

  const state = safeNullIfEmpty(address.state_code);
  const postal = safeNullIfEmpty(address.postal_code);
  if (state || postal) {
    const statePostal = [state, postal].filter(Boolean).join(" ");
    if (statePostal) {
      const plus4 = safeNullIfEmpty(address.plus_four_postal_code);
      localityPieces.push(plus4 ? `${statePostal}-${plus4}` : statePostal);
    }
  }

  const localityLine = localityPieces.join(", ").replace(/\s+/g, " ").trim();

  const segments = [streetLine, localityLine]
    .map((segment) => (segment || "").trim())
    .filter((segment) => segment.length);

  if (!segments.length) return null;

  const county = safeNullIfEmpty(address.county_name);
  if (county) {
    const countyUpper = county.toUpperCase();
    const alreadyHasCounty = segments.some((segment) =>
      segment.toUpperCase().includes(countyUpper),
    );
    if (!alreadyHasCounty) {
      segments.push(county);
    }
  }

  return segments.join(", ");
}

function extractComponentsFromFullAddress(raw) {
  const normalized = normalizeWhitespace(raw);
  if (!normalized) return null;

  const match = normalized.match(
    /^(\d+[A-Z]?(?:\s+\d+\/\d+)?)\s+([^,]+),\s*([^,]+),\s*([A-Z]{2})\s*(\d{5})(?:-(\d{4}))?$/i,
  );
  if (!match) return null;

  const [, numberPart, rawStreetSegment, rawCity, rawState, postalPart, plus4Part] =
    match;

  const streetInput = `${numberPart} ${rawStreetSegment}`.trim();
  const parsedStreet = parseLocationAddress(streetInput);

  const components = {
    streetNumber: parsedStreet.streetNumber || numberPart,
    streetPreDirectional: parsedStreet.streetPreDirectional || null,
    streetPostDirectional: parsedStreet.streetPostDirectional || null,
    streetSuffix: parsedStreet.streetSuffix
      ? mapStreetSuffixType(parsedStreet.streetSuffix)
      : null,
    unitIdentifier: parsedStreet.unitIdentifier || null,
    routeNumber: parsedStreet.routeNumber || null,
    cityName: sanitizeCityName(rawCity),
    stateCode: rawState ? rawState.trim().toUpperCase() : null,
    postalCode: postalPart || null,
    plus4: plus4Part || null,
  };

  let streetSegment = rawStreetSegment;
  if (!components.streetSuffix && streetSegment) {
    const streetTokens = streetSegment.split(/\s+/);
    if (streetTokens.length) {
      const lastToken = streetTokens[streetTokens.length - 1];
      const mappedSuffix = mapStreetSuffixType(lastToken);
      if (mappedSuffix) {
        components.streetSuffix = mappedSuffix;
        streetTokens.pop();
        streetSegment = streetTokens.join(" ");
      }
    }
  }

  const streetNameSource =
    parsedStreet.streetName ||
    (streetSegment
      ? streetSegment.replace(
          /\b(?:APT|UNIT|SUITE|STE|BLDG|BUILDING|FL|FLOOR|LOT|TRLR|TRAILER|SPC|SPACE)\b.*$/i,
          "",
        )
      : null);

  if (streetNameSource) {
    const formattedName = formatStreetNameCase(streetNameSource);
    components.streetName = formattedName
      ? formattedName.toUpperCase()
      : streetNameSource.toUpperCase();
  } else {
    components.streetName = null;
  }

  return components;
}

function parseLooseUnnormalizedAddress(raw) {
  const normalized = normalizeWhitespace(raw);
  if (!normalized) return null;

  const result = {
    streetNumber: null,
    streetName: null,
    streetPreDirectional: null,
    streetPostDirectional: null,
    streetSuffix: null,
    unitIdentifier: null,
    routeNumber: null,
    cityName: null,
    stateCode: null,
    postalCode: null,
    plus4: null,
  };

  let working = normalized
    .replace(/,\s*(?:USA|UNITED STATES?\.?)$/i, "")
    .trim();
  if (!working.length) {
    return result;
  }

  const zipMatch = working.match(/(\d{5})(?:[-\s](\d{4}))?$/);
  if (zipMatch) {
    result.postalCode = zipMatch[1];
    result.plus4 = zipMatch[2] || null;
    working = working.slice(0, zipMatch.index).replace(/[,]+$/, "").trim();
  }

  const stateMatch = working.match(/([A-Z]{2})$/i);
  if (stateMatch && /^[A-Z]{2}$/.test(stateMatch[1].toUpperCase())) {
    result.stateCode = stateMatch[1].toUpperCase();
    working = working.slice(0, stateMatch.index).replace(/[,]+$/, "").trim();
  }

  let streetSegment = working;
  let citySegment = null;

  if (working.includes(",")) {
    const lastCommaIndex = working.lastIndexOf(",");
    citySegment = working.slice(lastCommaIndex + 1).trim();
    streetSegment = working.slice(0, lastCommaIndex).trim();
  } else {
    const tokens = working.split(/\s+/);
    if (tokens.length > 1) {
      const cityTokens = [];
      while (tokens.length) {
        const token = tokens[tokens.length - 1];
        if (!token || /\d/.test(token)) {
          break;
        }
        cityTokens.unshift(tokens.pop());
        if (token.length > 3) {
          break;
        }
      }
      if (cityTokens.length) {
        citySegment = cityTokens.join(" ");
        streetSegment = tokens.join(" ").trim();
      }
    }
  }

  if (citySegment) {
    const sanitizedCity = sanitizeCityName(citySegment);
    if (sanitizedCity) {
      result.cityName = sanitizedCity;
    }
  }

  const parsedStreet = parseLocationAddress(streetSegment);
  if (parsedStreet.streetNumber) {
    result.streetNumber = parsedStreet.streetNumber;
  }
  if (parsedStreet.streetName) {
    result.streetName = parsedStreet.streetName;
  }
  if (parsedStreet.streetPreDirectional) {
    result.streetPreDirectional = parsedStreet.streetPreDirectional;
  }
  if (parsedStreet.streetPostDirectional) {
    result.streetPostDirectional = parsedStreet.streetPostDirectional;
  }
  if (parsedStreet.streetSuffix) {
    result.streetSuffix = parsedStreet.streetSuffix;
  }
  if (parsedStreet.unitIdentifier) {
    result.unitIdentifier = parsedStreet.unitIdentifier;
  }
  if (parsedStreet.routeNumber) {
    result.routeNumber = parsedStreet.routeNumber;
  }

  if ((!result.streetNumber || !result.streetName) && streetSegment) {
    const directMatch = streetSegment.match(/^(\d+[A-Z]?)\s+(.+)$/);
    if (directMatch) {
      if (!result.streetNumber) {
        result.streetNumber = directMatch[1];
      }
      if (!result.streetName) {
        const formatted = formatStreetNameCase(directMatch[2]);
        result.streetName = formatted
          ? formatted.toUpperCase()
          : directMatch[2].toUpperCase();
      }
    } else if (!result.streetName) {
      const formattedStreet = formatStreetNameCase(streetSegment);
      result.streetName = formattedStreet
        ? formattedStreet.toUpperCase()
        : streetSegment.toUpperCase();
    }
  }

  return result;
}

function enrichAddressFromUnnormalized(address, unnormalizedValue) {
  if (!address || typeof address !== "object") return;
  const normalizedSource = normalizeWhitespace(unnormalizedValue);
  if (!normalizedSource) return;

  const segments = normalizedSource
    .split(",")
    .map((segment) => segment.trim())
    .filter(Boolean);

  if (!segments.length) return;

  const streetSegment = segments[0];
  if (streetSegment) {
    const parsedStreet = parseLocationAddress(streetSegment);
    if (
      parsedStreet.streetNumber &&
      !RAW_ADDRESS_EXCLUDED_FIELDS.has("street_number") &&
      !address.street_number
    ) {
      address.street_number = safeNullIfEmpty(parsedStreet.streetNumber);
    }
    if (
      parsedStreet.streetName &&
      !RAW_ADDRESS_EXCLUDED_FIELDS.has("street_name") &&
      !address.street_name
    ) {
      const formatted = formatStreetNameCase(parsedStreet.streetName);
      address.street_name = formatted ? formatted.toUpperCase() : null;
    }
    if (
      parsedStreet.streetPreDirectional &&
      !RAW_ADDRESS_EXCLUDED_FIELDS.has("street_pre_directional_text") &&
      !address.street_pre_directional_text
    ) {
      address.street_pre_directional_text = parsedStreet.streetPreDirectional.toUpperCase();
    }
    if (
      parsedStreet.streetPostDirectional &&
      !RAW_ADDRESS_EXCLUDED_FIELDS.has("street_post_directional_text") &&
      !address.street_post_directional_text
    ) {
      address.street_post_directional_text = parsedStreet.streetPostDirectional.toUpperCase();
    }
    if (
      parsedStreet.streetSuffix &&
      !RAW_ADDRESS_EXCLUDED_FIELDS.has("street_suffix_type") &&
      !address.street_suffix_type
    ) {
      const mappedSuffix = mapStreetSuffixType(parsedStreet.streetSuffix);
      if (mappedSuffix) {
        address.street_suffix_type = mappedSuffix;
      }
    }
    if (parsedStreet.unitIdentifier && !address.unit_identifier) {
      address.unit_identifier = safeNullIfEmpty(parsedStreet.unitIdentifier);
    }
    if (parsedStreet.routeNumber && !address.route_number) {
      address.route_number = safeNullIfEmpty(parsedStreet.routeNumber);
    }
  }

  if (segments.length > 1) {
    const cityStateSegment = segments.slice(1).join(" ");
    const parsedCityState = parseCityStatePostal(cityStateSegment);
    if (parsedCityState.city && !address.city_name) {
      const cityCandidate = parsedCityState.city.toUpperCase();
      if (!/\d/.test(cityCandidate)) {
        address.city_name = cityCandidate;
      }
    }
    if (parsedCityState.state && !address.state_code) {
      address.state_code = parsedCityState.state.toUpperCase();
    }
    if (parsedCityState.postal && !address.postal_code) {
      address.postal_code = parsedCityState.postal;
    }
    if (parsedCityState.plus4 && !address.plus_four_postal_code) {
      address.plus_four_postal_code = parsedCityState.plus4;
    }
  }

  if (
    !hasMeaningfulAddressValue(address.street_number) ||
    !hasMeaningfulAddressValue(address.street_name) ||
    !hasMeaningfulAddressValue(address.city_name) ||
    !hasMeaningfulAddressValue(address.state_code) ||
    !hasMeaningfulAddressValue(address.postal_code)
  ) {
    const fallbackComponents = extractComponentsFromFullAddress(normalizedSource);
    if (fallbackComponents) {
      if (!hasMeaningfulAddressValue(address.street_number) && fallbackComponents.streetNumber) {
        address.street_number = fallbackComponents.streetNumber;
      }
      if (!hasMeaningfulAddressValue(address.street_name) && fallbackComponents.streetName) {
        address.street_name = fallbackComponents.streetName;
      }
      if (
        !hasMeaningfulAddressValue(address.street_pre_directional_text) &&
        fallbackComponents.streetPreDirectional
      ) {
        address.street_pre_directional_text = fallbackComponents.streetPreDirectional;
      }
      if (
        !hasMeaningfulAddressValue(address.street_post_directional_text) &&
        fallbackComponents.streetPostDirectional
      ) {
        address.street_post_directional_text = fallbackComponents.streetPostDirectional;
      }
      if (!hasMeaningfulAddressValue(address.street_suffix_type) && fallbackComponents.streetSuffix) {
        address.street_suffix_type = fallbackComponents.streetSuffix;
      }
      if (!hasMeaningfulAddressValue(address.unit_identifier) && fallbackComponents.unitIdentifier) {
        address.unit_identifier = fallbackComponents.unitIdentifier;
      }
      if (!hasMeaningfulAddressValue(address.route_number) && fallbackComponents.routeNumber) {
        address.route_number = fallbackComponents.routeNumber;
      }
      if (!hasMeaningfulAddressValue(address.city_name) && fallbackComponents.cityName) {
        address.city_name = fallbackComponents.cityName;
      }
      if (!hasMeaningfulAddressValue(address.state_code) && fallbackComponents.stateCode) {
        address.state_code = fallbackComponents.stateCode;
      }
      if (!hasMeaningfulAddressValue(address.postal_code) && fallbackComponents.postalCode) {
        address.postal_code = fallbackComponents.postalCode;
      }
      if (
        !hasMeaningfulAddressValue(address.plus_four_postal_code) &&
        fallbackComponents.plus4
      ) {
        address.plus_four_postal_code = fallbackComponents.plus4;
      }
    }
  }

  if (
    !hasMeaningfulAddressValue(address.street_number) ||
    !hasMeaningfulAddressValue(address.street_name) ||
    !hasMeaningfulAddressValue(address.city_name) ||
    !hasMeaningfulAddressValue(address.state_code) ||
    !hasMeaningfulAddressValue(address.postal_code)
  ) {
    const looseComponents = parseLooseUnnormalizedAddress(normalizedSource);
    if (looseComponents) {
      if (
        !hasMeaningfulAddressValue(address.street_number) &&
        looseComponents.streetNumber
      ) {
        address.street_number = safeNullIfEmpty(looseComponents.streetNumber);
      }
      if (
        !hasMeaningfulAddressValue(address.street_name) &&
        looseComponents.streetName
      ) {
        const formattedName = formatStreetNameCase(looseComponents.streetName);
        address.street_name = formattedName
          ? formattedName.toUpperCase()
          : looseComponents.streetName.toUpperCase();
      }
      if (
        !hasMeaningfulAddressValue(address.street_pre_directional_text) &&
        looseComponents.streetPreDirectional
      ) {
        address.street_pre_directional_text =
          looseComponents.streetPreDirectional.toUpperCase();
      }
      if (
        !hasMeaningfulAddressValue(address.street_post_directional_text) &&
        looseComponents.streetPostDirectional
      ) {
        address.street_post_directional_text =
          looseComponents.streetPostDirectional.toUpperCase();
      }
      if (
        !hasMeaningfulAddressValue(address.street_suffix_type) &&
        looseComponents.streetSuffix
      ) {
        const mappedSuffix = mapStreetSuffixType(looseComponents.streetSuffix);
        if (mappedSuffix) {
          address.street_suffix_type = mappedSuffix;
        }
      }
      if (
        !hasMeaningfulAddressValue(address.unit_identifier) &&
        looseComponents.unitIdentifier
      ) {
        address.unit_identifier = safeNullIfEmpty(
          looseComponents.unitIdentifier,
        );
      }
      if (
        !hasMeaningfulAddressValue(address.route_number) &&
        looseComponents.routeNumber
      ) {
        address.route_number = safeNullIfEmpty(looseComponents.routeNumber);
      }
      if (
        !hasMeaningfulAddressValue(address.city_name) &&
        looseComponents.cityName
      ) {
        address.city_name = looseComponents.cityName;
      }
      if (
        !hasMeaningfulAddressValue(address.state_code) &&
        looseComponents.stateCode
      ) {
        address.state_code = looseComponents.stateCode;
      }
      if (
        !hasMeaningfulAddressValue(address.postal_code) &&
        looseComponents.postalCode
      ) {
        const sanitizedPostal = sanitizePostalCode(looseComponents.postalCode);
        if (sanitizedPostal) {
          address.postal_code = sanitizedPostal;
        }
      }
      if (
        !hasMeaningfulAddressValue(address.plus_four_postal_code) &&
        looseComponents.plus4
      ) {
        const normalizedPlus4 = sanitizePlus4(looseComponents.plus4);
        if (normalizedPlus4) {
          address.plus_four_postal_code = normalizedPlus4;
        }
      }
    }
  }

  if (address.state_code && !address.country_code) {
    address.country_code = "US";
  }
}

