function stabilizeAddressForSchema(addressFilePath) {
  if (!addressFilePath || !fs.existsSync(addressFilePath)) {
    return;
  }

  let payload;
  try {
    payload = readJSON(addressFilePath);
  } catch {
    removeFileIfExists(addressFilePath);
    return;
  }

  if (!payload || typeof payload !== "object" || Array.isArray(payload)) {
    removeFileIfExists(addressFilePath);
    return;
  }

  const normalizedProbe =
    ensureAddressOutputFieldPresence({ ...payload }) || { ...payload };

  const trimmedUnnormalized =
    typeof payload.unnormalized_address === "string"
      ? payload.unnormalized_address.trim()
      : "";

  const normalizedSurface = { ...NORMALIZED_ADDRESS_SCHEMA_TEMPLATE };
  for (const field of NORMALIZED_ADDRESS_FIELDS) {
    const candidate = Object.prototype.hasOwnProperty.call(payload, field)
      ? payload[field]
      : null;
    normalizedSurface[field] = sanitizeAddressFieldValue(field, candidate);
  }

  if (!normalizedSurface.postal_code) {
    normalizedSurface.plus_four_postal_code = null;
  }
  if (
    normalizedSurface.state_code &&
    !normalizedSurface.country_code
  ) {
    normalizedSurface.country_code = "US";
  }
  if (
    (normalizedSurface.latitude == null) !==
    (normalizedSurface.longitude == null)
  ) {
    normalizedSurface.latitude = null;
    normalizedSurface.longitude = null;
  }

  const hasNormalizedCoverage =
    NORMALIZED_ADDRESS_REQUIRED_STRING_FIELDS.every((field) =>
      hasMeaningfulAddressValue(normalizedSurface[field]),
    ) && hasNormalizedCountyCoverage(normalizedSurface);

  const requestIdentifier = safeNullIfEmpty(payload.request_identifier);
  const preparedSourceHttpRequest = prepareSourceHttpRequest(
    payload.source_http_request,
  );

  if (hasNormalizedCoverage) {
    const normalizedOutput =
      ensureAddressOutputFieldPresence(normalizedSurface) ||
      normalizedSurface;

    if (requestIdentifier) {
      normalizedOutput.request_identifier = requestIdentifier;
    } else if (
      Object.prototype.hasOwnProperty.call(
        normalizedOutput,
        "request_identifier",
      )
    ) {
      normalizedOutput.request_identifier = null;
    }

    if (preparedSourceHttpRequest) {
      normalizedOutput.source_http_request = deepClone(
        preparedSourceHttpRequest,
      );
    } else if (
      Object.prototype.hasOwnProperty.call(
        normalizedOutput,
        "source_http_request",
      )
    ) {
      delete normalizedOutput.source_http_request;
    }

    if (Object.prototype.hasOwnProperty.call(normalizedOutput, "unnormalized_address")) {
      delete normalizedOutput.unnormalized_address;
    }

    fs.writeFileSync(
      addressFilePath,
      JSON.stringify(normalizedOutput, null, 2),
    );
    return;
  }

  let rawString = trimmedUnnormalized;
  if (!rawString.length) {
    rawString =
      composeFallbackUnnormalizedAddressFromFields(normalizedSurface) || "";
  }

  if (!rawString.length) {
    removeFileIfExists(addressFilePath);
    return;
  }

  const rawOutput = { ...RAW_ADDRESS_SCHEMA_TEMPLATE };
  for (const field of RAW_ADDRESS_OUTPUT_FIELDS) {
    rawOutput[field] = normalizedSurface[field];
  }

  rawOutput.unnormalized_address = rawString;

  if (!rawOutput.postal_code) {
    rawOutput.plus_four_postal_code = null;
  }
  if (rawOutput.state_code && !rawOutput.country_code) {
    rawOutput.country_code = "US";
  }
  if (
    (rawOutput.latitude == null) !==
    (rawOutput.longitude == null)
  ) {
    rawOutput.latitude = null;
    rawOutput.longitude = null;
  }

  if (requestIdentifier) {
    rawOutput.request_identifier = requestIdentifier;
  } else if (
    Object.prototype.hasOwnProperty.call(rawOutput, "request_identifier")
  ) {
    rawOutput.request_identifier = null;
  }

  if (preparedSourceHttpRequest) {
    rawOutput.source_http_request = deepClone(preparedSourceHttpRequest);
  } else if (
    Object.prototype.hasOwnProperty.call(rawOutput, "source_http_request")
  ) {
    delete rawOutput.source_http_request;
  }

  const surfaced =
    ensureAddressOutputFieldPresence(rawOutput) || rawOutput;

  writeJSON(addressFilePath, surfaced);
}

