function buildAddressPayloadForWrite(address, variantHint = null) {
  if (!address || typeof address !== "object") return null;

  const hasRawString =
    typeof address.unnormalized_address === "string" &&
    address.unnormalized_address.trim().length > 0;

  const resolvedVariant =
    variantHint === "normalized"
      ? "normalized"
      : variantHint === "raw"
        ? "raw"
        : hasRawString
          ? "raw"
          : "normalized";

  const template =
    resolvedVariant === "raw"
      ? { ...RAW_ADDRESS_SCHEMA_TEMPLATE }
      : { ...NORMALIZED_ADDRESS_SCHEMA_TEMPLATE };

  const materialized = { ...template };

  for (const field of Object.keys(template)) {
    let value = Object.prototype.hasOwnProperty.call(address, field)
      ? address[field]
      : null;

    if (value === undefined || value === null) {
      materialized[field] = null;
      continue;
    }

    if (ADDRESS_COORDINATE_FIELDS.includes(field)) {
      const numeric = parseCoordinate(value);
      materialized[field] = Number.isFinite(numeric) ? numeric : null;
      continue;
    }

    if (typeof value === "string") {
      const trimmed = value.trim();
      materialized[field] = trimmed.length ? trimmed : null;
      continue;
    }

    materialized[field] = value;
  }

  if (resolvedVariant === "raw") {
    const trimmed =
      typeof address.unnormalized_address === "string"
        ? address.unnormalized_address.trim()
        : "";
    if (!trimmed.length) {
      return null;
    }
    materialized.unnormalized_address = trimmed;
    return buildMinimalRawAddressForSchema(materialized);
  }

  if (Object.prototype.hasOwnProperty.call(materialized, "unnormalized_address")) {
    delete materialized.unnormalized_address;
  }

  if (!materialized.postal_code) {
    materialized.plus_four_postal_code = null;
  }

  if (materialized.state_code && !materialized.country_code) {
    materialized.country_code = "US";
  }

  const requestIdentifier = safeNullIfEmpty(address.request_identifier);
  if (requestIdentifier) {
    materialized.request_identifier = requestIdentifier;
  } else if (Object.prototype.hasOwnProperty.call(materialized, "request_identifier")) {
    delete materialized.request_identifier;
  }

  const preparedSource = prepareSourceHttpRequest(address.source_http_request);
  if (preparedSource) {
    materialized.source_http_request = deepClone(preparedSource);
  } else if (Object.prototype.hasOwnProperty.call(materialized, "source_http_request")) {
    delete materialized.source_http_request;
  }

  return materialized;
}

function buildCountyAddressOutput(candidate) {
  if (!candidate || typeof candidate !== "object") return null;

  const normalizedSurface = NORMALIZED_ADDRESS_FIELDS.reduce((acc, field) => {
    acc[field] = null;
    return acc;
  }, {});

  for (const field of NORMALIZED_ADDRESS_FIELDS) {
    const hasField = Object.prototype.hasOwnProperty.call(candidate, field);
    let value = hasField ? candidate[field] : null;

    if (ADDRESS_COORDINATE_FIELDS.includes(field)) {
      const numeric = parseCoordinate(value);
      normalizedSurface[field] = Number.isFinite(numeric) ? numeric : null;
      continue;
    }

    const normalizedValue = normalizeAddressFieldForSchema(field, value);
    if (normalizedValue === undefined || normalizedValue === null) {
      normalizedSurface[field] = null;
      continue;
    }

    if (typeof normalizedValue === "string") {
      const trimmed = normalizedValue.trim();
      normalizedSurface[field] = trimmed.length ? trimmed : null;
      continue;
    }

    normalizedSurface[field] = normalizedValue;
  }

  const hasLatitude = Number.isFinite(normalizedSurface.latitude);
  const hasLongitude = Number.isFinite(normalizedSurface.longitude);
  if (hasLatitude !== hasLongitude) {
    normalizedSurface.latitude = null;
    normalizedSurface.longitude = null;
  }

  if (!normalizedSurface.postal_code) {
    normalizedSurface.plus_four_postal_code = null;
  }
  if (normalizedSurface.state_code && !normalizedSurface.country_code) {
    normalizedSurface.country_code = "US";
  }

  const requestIdentifier = safeNullIfEmpty(candidate.request_identifier);
  const preparedSource = prepareSourceHttpRequest(
    candidate.source_http_request,
  );

  const trimmedUnnormalized =
    typeof candidate.unnormalized_address === "string"
      ? candidate.unnormalized_address.trim()
      : "";

  const hasNormalizedCoverage = hasNormalizedCountyCoverage(normalizedSurface);

  if (hasNormalizedCoverage && !trimmedUnnormalized.length) {
    const normalizedOutput = { ...normalizedSurface };
    if (requestIdentifier) {
      normalizedOutput.request_identifier = requestIdentifier;
    }
    if (preparedSource) {
      normalizedOutput.source_http_request = deepClone(preparedSource);
    }
    return normalizedOutput;
  }

  if (trimmedUnnormalized.length) {
    const rawOutput = {
      ...normalizedSurface,
      unnormalized_address: trimmedUnnormalized,
    };
    if (requestIdentifier) {
      rawOutput.request_identifier = requestIdentifier;
    }
    if (preparedSource) {
      rawOutput.source_http_request = deepClone(preparedSource);
    }
    const rawWithDefaults =
      ensureRawAddressSchemaDefaults(rawOutput) || rawOutput;

    if (hasRawAddressRequiredValues(rawWithDefaults)) {
      return rawWithDefaults;
    }

    const normalizedSeed = {
      ...normalizedSurface,
      latitude: rawWithDefaults.latitude,
      longitude: rawWithDefaults.longitude,
    };

    const normalizedFromUnnormalized =
      buildNormalizedAddressFromUnnormalized(
        normalizedSeed,
        trimmedUnnormalized,
        {
          seed: normalizedSeed,
          latitudeCandidates: Number.isFinite(rawWithDefaults.latitude)
            ? [rawWithDefaults.latitude]
            : [],
          longitudeCandidates: Number.isFinite(rawWithDefaults.longitude)
            ? [rawWithDefaults.longitude]
            : [],
        },
      ) || normalizedSeed;

    const normalizedSurfaceFallback =
      ensureNormalizedAddressSchemaSurface(normalizedFromUnnormalized) || null;

    if (normalizedSurfaceFallback) {
      const hasNormalizedCoverageFallback =
        NORMALIZED_ADDRESS_REQUIRED_STRING_FIELDS.every(
          (field) =>
            typeof normalizedSurfaceFallback[field] === "string" &&
            normalizedSurfaceFallback[field].trim().length > 0,
        );

      if (hasNormalizedCoverageFallback) {
        if (requestIdentifier) {
          normalizedSurfaceFallback.request_identifier = requestIdentifier;
        }
        if (preparedSource) {
          normalizedSurfaceFallback.source_http_request =
            deepClone(preparedSource);
        }
        if (
          Object.prototype.hasOwnProperty.call(
            normalizedSurfaceFallback,
            "unnormalized_address",
          )
        ) {
          delete normalizedSurfaceFallback.unnormalized_address;
        }
        return normalizedSurfaceFallback;
      }
    }

    return null;
  }

  return null;
}

function enforceFinalAddressSchemaOutput(addressFilePath) {
  if (!addressFilePath || !fs.existsSync(addressFilePath)) {
    return;
  }

  let payload;
  try {
    payload = readJSON(addressFilePath);
  } catch (err) {
    removeFileIfExists(addressFilePath);
    return;
  }

  if (!payload || typeof payload !== "object") {
    removeFileIfExists(addressFilePath);
    return;
  }

  const trimmedUnnormalized =
    typeof payload.unnormalized_address === "string"
      ? payload.unnormalized_address.trim()
      : "";
  const hasRawUnnormalized = trimmedUnnormalized.length > 0;

  const sanitizeField = (field, value) => {
    const normalized = normalizeAddressFieldForSchema(field, value);
    if (normalized === undefined || normalized === null) {
      return null;
    }
    if (ADDRESS_COORDINATE_FIELDS.includes(field)) {
      const numeric = parseCoordinate(normalized);
      return Number.isFinite(numeric) ? numeric : null;
    }
    if (typeof normalized === "string") {
      const trimmed = normalized.trim();
      return trimmed.length ? trimmed : null;
    }
    if (typeof normalized === "number") {
      return Number.isFinite(normalized) ? normalized : null;
    }
    if (typeof normalized === "boolean") {
      return normalized;
    }
    return null;
  };

  const normalizedSurface = NORMALIZED_ADDRESS_FIELDS.reduce((acc, field) => {
    const rawValue = Object.prototype.hasOwnProperty.call(payload, field)
      ? payload[field]
      : null;
    acc[field] = sanitizeField(field, rawValue);
    return acc;
  }, {});

  const hasNormalizedCoverage =
    NORMALIZED_ADDRESS_REQUIRED_STRING_FIELDS.every(
      (field) =>
        typeof normalizedSurface[field] === "string" &&
        normalizedSurface[field].trim().length > 0,
    ) && hasNormalizedCountyCoverage(normalizedSurface);

  const hadRequestIdentifier = Object.prototype.hasOwnProperty.call(
    payload,
    "request_identifier",
  );
  const hadSourceHttpRequest = Object.prototype.hasOwnProperty.call(
    payload,
    "source_http_request",
  );
  const requestIdentifier = safeNullIfEmpty(payload.request_identifier);
  const preparedSource = prepareSourceHttpRequest(
    payload.source_http_request,
  );

  if (hasRawUnnormalized) {
    const rawCandidate = {
      ...payload,
      ...normalizedSurface,
      unnormalized_address: trimmedUnnormalized,
    };
    let minimalRaw = composeMinimalRawAddress(rawCandidate);
    if (minimalRaw) {
      if (requestIdentifier) {
        minimalRaw.request_identifier = requestIdentifier;
      } else if (
        Object.prototype.hasOwnProperty.call(minimalRaw, "request_identifier")
      ) {
        delete minimalRaw.request_identifier;
      }
      if (preparedSource) {
        minimalRaw.source_http_request = deepClone(preparedSource);
      } else if (
        Object.prototype.hasOwnProperty.call(
          minimalRaw,
          "source_http_request",
        )
      ) {
        delete minimalRaw.source_http_request;
      }
      const surfacedRaw = finalizeAddressPayloadForOutput(
        minimalRaw,
        "raw",
      );
      if (surfacedRaw) {
        writeJSON(addressFilePath, surfacedRaw);
      } else {
        removeFileIfExists(addressFilePath);
      }
    } else {
      removeFileIfExists(addressFilePath);
    }
    return;
  }

  if (hasNormalizedCoverage) {
    const normalizedOutput = { ...NORMALIZED_ADDRESS_SCHEMA_TEMPLATE };
    for (const field of NORMALIZED_ADDRESS_FIELDS) {
      const value = normalizedSurface[field];
      normalizedOutput[field] =
        value === undefined || value === null ? null : value;
    }
    if (!normalizedOutput.postal_code) {
      normalizedOutput.plus_four_postal_code = null;
    }
    if (normalizedOutput.state_code && !normalizedOutput.country_code) {
      normalizedOutput.country_code = "US";
    }
    if (requestIdentifier) {
      normalizedOutput.request_identifier = requestIdentifier;
    }
    if (preparedSource) {
      normalizedOutput.source_http_request = deepClone(preparedSource);
    }
    const surfacedNormalized = finalizeAddressPayloadForOutput(
      normalizedOutput,
      "normalized",
    );
    if (surfacedNormalized) {
      writeJSON(addressFilePath, surfacedNormalized);
    } else {
      removeFileIfExists(addressFilePath);
    }
    return;
  }

  removeFileIfExists(addressFilePath);
}

