function finalizeAddressSchemaOutput(addressFilePath, options = {}) {
  if (!addressFilePath || !fs.existsSync(addressFilePath)) {
    return;
  }

  let payload;
  try {
    payload = readJSON(addressFilePath);
  } catch (err) {
    removeFileIfExists(addressFilePath);
    return;
  }

  if (!payload || typeof payload !== "object") {
    removeFileIfExists(addressFilePath);
    return;
  }

  const {
    fieldSources = [],
    fieldFallbacks = {},
    unnormalizedCandidates = [],
    requestIdentifierCandidates = [],
    sourceHttpRequestCandidates = [],
    coordinateFallback = {},
  } = options || {};

  const additionalSources = Array.isArray(fieldSources)
    ? fieldSources.filter((candidate) => candidate && typeof candidate === "object")
    : [];

  const candidateSources = [payload, ...additionalSources];
  const fallbackMap =
    fieldFallbacks && typeof fieldFallbacks === "object" ? fieldFallbacks : {};

  const coordinateFallbackMap =
    coordinateFallback && typeof coordinateFallback === "object"
      ? coordinateFallback
      : {};

  const collectFieldCandidates = (field) => {
    const collected = [];
    for (const source of candidateSources) {
      if (
        source &&
        typeof source === "object" &&
        Object.prototype.hasOwnProperty.call(source, field)
      ) {
        collected.push(source[field]);
      }
    }

    if (Object.prototype.hasOwnProperty.call(fallbackMap, field)) {
      const fallbackValue = fallbackMap[field];
      if (Array.isArray(fallbackValue)) {
        collected.push(...fallbackValue);
      } else if (fallbackValue !== undefined) {
        collected.push(fallbackValue);
      }
    }

    if (ADDRESS_COORDINATE_FIELDS.includes(field)) {
      if (Object.prototype.hasOwnProperty.call(coordinateFallbackMap, field)) {
        collected.push(coordinateFallbackMap[field]);
      }
    }

    return collected;
  };

  const resolveFieldValue = (field) => {
    const candidates = collectFieldCandidates(field);
    for (const candidate of candidates) {
      if (candidate === undefined) {
        continue;
      }
      if (candidate === null) {
        return null;
      }

      if (ADDRESS_COORDINATE_FIELDS.includes(field)) {
        const numeric = parseCoordinate(candidate);
        if (Number.isFinite(numeric)) {
          return numeric;
        }
        continue;
      }

      const normalized = normalizeAddressFieldForSchema(field, candidate);
      if (normalized !== undefined && normalized !== null) {
        return normalized;
      }
    }
    return null;
  };

  const normalizedSurface = { ...NORMALIZED_ADDRESS_SCHEMA_TEMPLATE };
  for (const field of NORMALIZED_ADDRESS_FIELDS) {
    normalizedSurface[field] = resolveFieldValue(field);
  }

  if (
    (normalizedSurface.latitude == null) !==
    (normalizedSurface.longitude == null)
  ) {
    normalizedSurface.latitude = null;
    normalizedSurface.longitude = null;
  }

  if (!normalizedSurface.postal_code) {
    normalizedSurface.plus_four_postal_code = null;
  }
  if (normalizedSurface.state_code && !normalizedSurface.country_code) {
    normalizedSurface.country_code = "US";
  }

  const hasNormalizedCoverage =
    NORMALIZED_ADDRESS_REQUIRED_STRING_FIELDS.every(
      (field) =>
        typeof normalizedSurface[field] === "string" &&
        normalizedSurface[field].trim().length > 0,
    ) && hasNormalizedCountyCoverage(normalizedSurface);

  const requestIdentifierOptions = [
    payload.request_identifier,
    ...(Array.isArray(requestIdentifierCandidates)
      ? requestIdentifierCandidates
      : []),
  ];

  const resolvedRequestIdentifierCandidates =
    collectNonEmptyStrings(requestIdentifierOptions);
  const resolvedRequestIdentifier = resolvedRequestIdentifierCandidates.length
    ? resolvedRequestIdentifierCandidates[0]
    : null;
  const hadRequestIdentifier = Object.prototype.hasOwnProperty.call(
    payload,
    "request_identifier",
  );

  const sourceHttpQueue = [];
  if (payload.source_http_request) {
    sourceHttpQueue.push(payload.source_http_request);
  }
  if (Array.isArray(sourceHttpRequestCandidates)) {
    sourceHttpQueue.push(...sourceHttpRequestCandidates);
  }

  let resolvedSourceHttpRequest = null;
  for (const candidate of sourceHttpQueue) {
    const prepared = prepareSourceHttpRequest(candidate);
    if (prepared) {
      resolvedSourceHttpRequest = prepared;
      break;
    }
  }
  const hadSourceHttpRequest = Object.prototype.hasOwnProperty.call(
    payload,
    "source_http_request",
  );

  const unnormalizedQueue = [];
  if (typeof payload.unnormalized_address === "string") {
    unnormalizedQueue.push(payload.unnormalized_address);
  }
  if (Array.isArray(unnormalizedCandidates)) {
    unnormalizedQueue.push(...unnormalizedCandidates);
  }
  const resolvedUnnormalized = safeNullIfEmpty(
    resolveFirstNonEmptyString(unnormalizedQueue),
  );

  if (hasNormalizedCoverage) {
    const normalizedOutput = { ...NORMALIZED_ADDRESS_SCHEMA_TEMPLATE };
    for (const field of NORMALIZED_ADDRESS_FIELDS) {
      const value = normalizedSurface[field];
      normalizedOutput[field] =
        value === undefined || value === null ? null : value;
    }

    if (!normalizedOutput.postal_code) {
      normalizedOutput.plus_four_postal_code = null;
    }
    if (normalizedOutput.state_code && !normalizedOutput.country_code) {
      normalizedOutput.country_code = "US";
    }

    if (resolvedRequestIdentifier) {
      normalizedOutput.request_identifier = resolvedRequestIdentifier;
    } else if (hadRequestIdentifier) {
      normalizedOutput.request_identifier = null;
    }

    if (resolvedSourceHttpRequest) {
      normalizedOutput.source_http_request = deepClone(
        resolvedSourceHttpRequest,
      );
    } else if (hadSourceHttpRequest) {
      normalizedOutput.source_http_request = null;
    }

    writeJSON(addressFilePath, normalizedOutput);
    return;
  }

  if (resolvedUnnormalized) {
    const rawOutput = { ...RAW_ADDRESS_SCHEMA_TEMPLATE };
    for (const field of RAW_ADDRESS_OUTPUT_FIELDS) {
      const value = resolveFieldValue(field);
      rawOutput[field] = value === undefined || value === null ? null : value;
    }

    if (
      (rawOutput.latitude == null) !== (rawOutput.longitude == null)
    ) {
      rawOutput.latitude = null;
      rawOutput.longitude = null;
    }
    if (!rawOutput.postal_code) {
      rawOutput.plus_four_postal_code = null;
    }
    if (rawOutput.state_code && !rawOutput.country_code) {
      rawOutput.country_code = "US";
    }

    rawOutput.unnormalized_address = resolvedUnnormalized;

    backfillNormalizedAddressFields(rawOutput, {
      unnormalized: resolvedUnnormalized,
      fallbackCity: payload.city_name,
      fallbackState: payload.state_code,
      fallbackPostal: payload.postal_code,
      fallbackPlus4: payload.plus_four_postal_code,
      fallbackCounty: payload.county_name,
      fallbackCountry: payload.country_code,
      fallbackMunicipality: payload.municipality_name,
      fallbackUnit: payload.unit_identifier,
      fallbackRoute: payload.route_number,
      fallbackLatitude: payload.latitude,
      fallbackLongitude: payload.longitude,
      fallbackTownship: payload.township,
      fallbackRange: payload.range,
      fallbackSection: payload.section,
      fallbackBlock: payload.block,
      fallbackLot: payload.lot,
      fallbackStreetNumber: payload.street_number,
      fallbackStreetName: payload.street_name,
      fallbackStreetPreDirectional: payload.street_pre_directional_text,
      fallbackStreetPostDirectional: payload.street_post_directional_text,
      fallbackStreetSuffix: payload.street_suffix_type,
    });

    backfillNormalizedAddressFields(rawOutput, {
      unnormalized: resolvedUnnormalized,
      fallbackCity: payload.city_name,
      fallbackState: payload.state_code,
      fallbackPostal: payload.postal_code,
      fallbackPlus4: payload.plus_four_postal_code,
      fallbackCounty: payload.county_name,
      fallbackCountry: payload.country_code,
      fallbackMunicipality: payload.municipality_name,
      fallbackUnit: payload.unit_identifier,
      fallbackRoute: payload.route_number,
      fallbackLatitude: payload.latitude,
      fallbackLongitude: payload.longitude,
      fallbackTownship: payload.township,
      fallbackRange: payload.range,
      fallbackSection: payload.section,
      fallbackBlock: payload.block,
      fallbackLot: payload.lot,
      fallbackStreetNumber: payload.street_number,
      fallbackStreetName: payload.street_name,
      fallbackStreetPreDirectional: payload.street_pre_directional_text,
      fallbackStreetPostDirectional: payload.street_post_directional_text,
      fallbackStreetSuffix: payload.street_suffix_type,
    });

    if (resolvedRequestIdentifier) {
      rawOutput.request_identifier = resolvedRequestIdentifier;
    } else if (hadRequestIdentifier) {
      rawOutput.request_identifier = null;
    }

    if (resolvedSourceHttpRequest) {
      rawOutput.source_http_request = deepClone(resolvedSourceHttpRequest);
    } else if (hadSourceHttpRequest) {
      rawOutput.source_http_request = null;
    }

    writeJSON(addressFilePath, rawOutput);
    return;
  }

  removeFileIfExists(addressFilePath);
}

function enforceFinalCountyAddressSchema(addressFilePath, options = {}) {
  if (!addressFilePath || !fs.existsSync(addressFilePath)) {
    return;
  }

  let payload;
  try {
    payload = readJSON(addressFilePath);
  } catch (err) {
    removeFileIfExists(addressFilePath);
    return;
  }

  if (!payload || typeof payload !== "object") {
    removeFileIfExists(addressFilePath);
    return;
  }

  const {
    unnormalizedCandidates = [],
    requestIdentifierCandidates = [],
    sourceHttpRequestCandidates = [],
    coordinateFallback = {},
  } = options || {};

  const collectCandidates = (extra, accumulator = []) => {
    if (extra == null) {
      return accumulator;
    }
    if (Array.isArray(extra)) {
      for (const item of extra) {
        if (item != null) {
          accumulator.push(item);
        }
      }
      return accumulator;
    }
    accumulator.push(extra);
    return accumulator;
  };

  const normalizedSurface = { ...NORMALIZED_ADDRESS_SCHEMA_TEMPLATE };
  for (const field of NORMALIZED_ADDRESS_FIELDS) {
    const normalizedValue = normalizeAddressFieldForSchema(field, payload[field]);
    normalizedSurface[field] =
      normalizedValue === undefined || normalizedValue === null ? null : normalizedValue;
  }

  const resolvedCoordinateFallback =
    coordinateFallback && typeof coordinateFallback === "object"
      ? coordinateFallback
      : {};

  for (const coordField of ADDRESS_COORDINATE_FIELDS) {
    if (
      !Number.isFinite(normalizedSurface[coordField]) &&
      Number.isFinite(resolvedCoordinateFallback[coordField])
    ) {
      normalizedSurface[coordField] = resolvedCoordinateFallback[coordField];
    }
  }

  const resolvedRequestIdentifier = safeNullIfEmpty(
    resolveFirstNonEmptyString(
      collectCandidates(requestIdentifierCandidates, [
        payload.request_identifier,
      ]),
    ),
  );

  const resolvedSourceHttpRequest = (function resolveSourceCandidate() {
    const candidates = collectCandidates(sourceHttpRequestCandidates, [
      payload.source_http_request,
    ]);
    for (const candidate of candidates) {
      const prepared = prepareSourceHttpRequest(candidate);
      if (prepared) {
        return prepared;
      }
    }
    return null;
  })();

  const hasNormalizedCoverage =
    NORMALIZED_ADDRESS_REQUIRED_STRING_FIELDS.every(
      (field) =>
        typeof normalizedSurface[field] === "string" &&
        normalizedSurface[field].trim().length > 0,
    ) && hasNormalizedCountyCoverage(normalizedSurface);

  if (hasNormalizedCoverage) {
    const normalizedOutput = { ...NORMALIZED_ADDRESS_SCHEMA_TEMPLATE };
    for (const field of NORMALIZED_ADDRESS_FIELDS) {
      normalizedOutput[field] = normalizedSurface[field];
    }
    if (!normalizedOutput.postal_code) {
      normalizedOutput.plus_four_postal_code = null;
    }
    if (normalizedOutput.state_code && !normalizedOutput.country_code) {
      normalizedOutput.country_code = "US";
    }
    if (resolvedRequestIdentifier) {
      normalizedOutput.request_identifier = resolvedRequestIdentifier;
    }
    if (resolvedSourceHttpRequest) {
      normalizedOutput.source_http_request = deepClone(resolvedSourceHttpRequest);
    }
    writeJSON(addressFilePath, normalizedOutput);
    return;
  }

  const rawUnnormalizedCandidates = collectCandidates(
    unnormalizedCandidates,
    typeof payload.unnormalized_address === "string"
      ? [payload.unnormalized_address]
      : [],
  );

  const reconstructedUnnormalized = composeUnnormalizedAddress({
    ...normalizedSurface,
    unnormalized_address: payload.unnormalized_address,
  });

  if (reconstructedUnnormalized) {
    rawUnnormalizedCandidates.push(reconstructedUnnormalized);
  }

  const resolvedUnnormalized = resolveFirstNonEmptyString(
    rawUnnormalizedCandidates,
  );
  const trimmedUnnormalized = safeNullIfEmpty(resolvedUnnormalized);

  if (!trimmedUnnormalized) {
    removeFileIfExists(addressFilePath);
    return;
  }

  const rawOutput = { ...RAW_ADDRESS_SCHEMA_TEMPLATE };
  for (const field of NORMALIZED_ADDRESS_FIELDS) {
    rawOutput[field] = normalizedSurface[field];
  }
  for (const coordField of ADDRESS_COORDINATE_FIELDS) {
    if (
      !Number.isFinite(rawOutput[coordField]) &&
      Number.isFinite(resolvedCoordinateFallback[coordField])
    ) {
      rawOutput[coordField] = resolvedCoordinateFallback[coordField];
    }
  }

  rawOutput.unnormalized_address = trimmedUnnormalized;

  if (!rawOutput.postal_code) {
    rawOutput.plus_four_postal_code = null;
  }
  if (rawOutput.state_code && !rawOutput.country_code) {
    rawOutput.country_code = "US";
  }
  if (resolvedRequestIdentifier) {
    rawOutput.request_identifier = resolvedRequestIdentifier;
  } else if (
    Object.prototype.hasOwnProperty.call(rawOutput, "request_identifier")
  ) {
    delete rawOutput.request_identifier;
  }
  if (resolvedSourceHttpRequest) {
    rawOutput.source_http_request = deepClone(resolvedSourceHttpRequest);
  } else if (
    Object.prototype.hasOwnProperty.call(rawOutput, "source_http_request")
  ) {
    delete rawOutput.source_http_request;
  }

  fs.writeFileSync(addressFilePath, JSON.stringify(rawOutput, null, 2));
}

